(325785,36199,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ... Männer trommeln in diesem Dorf, so cool.'::text,'zehn'::text,'zehnte'::text,'Zehnen'::text,'Alter, zehn Männer trommeln in diesem Dorf, so cool.'::text),
(325789,36199,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, ... чоловіків грають на барабанах у цьому селі, так круто.'::text,'десять'::text,'десятий'::text,'десятки'::text,'Чувак, десять чоловіків грають на барабанах у цьому селі, так круто.'::text),
(325788,36199,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... hombres tocan los tambores en este pueblo, qué guay.'::text,'diez'::text,'décimo'::text,'diez'::text,'Tío, diez hombres tocan los tambores en este pueblo, qué guay.'::text),
(325787,36199,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, ... hommes jouent du tambour dans ce village, trop cool.'::text,'dix'::text,'dixième'::text,'dix'::text,'Mec, dix hommes jouent du tambour dans ce village, trop cool.'::text),
(325790,36199,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu köyde ... adam davul çalıyor, çok havalı.'::text,'on'::text,'onuncu'::text,'onlar'::text,'Kanka, bu köyde on adam davul çalıyor, çok havalı.'::text),
(325791,36199,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ebben a faluban ... férfi dobol, nagyon menő.'::text,'tíz'::text,'tizedik'::text,'tízesek'::text,'Tesó, ebben a faluban tíz férfi dobol, nagyon menő.'::text),
(321474,35720,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Party, eh klar: Sie ... zwölf süße Cupcakes für null Gäste.'::text,'backte'::text,'backt'::text,'backte'::text,'Tolle Party, eh klar: Sie backte zwölf süße Cupcakes für null Gäste.'::text),
(321478,35720,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова вечірка, звісно: вона ... дванадцять солодких капкейків для нуля гостей.'::text,'спекла'::text,'пече'::text,'спекла'::text,'Чудова вечірка, звісно: вона спекла дванадцять солодких капкейків для нуля гостей.'::text),
(321477,35720,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fiesta genial, claro: ella ... doce cupcakes dulces para cero invitados.'::text,'hizo'::text,'hace'::text,'hizo'::text,'Fiesta genial, claro: ella hizo doce cupcakes dulces para cero invitados.'::text),
(321476,35720,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super fête, évidemment : elle ... douze cupcakes sucrés pour zéro invité.'::text,'a fait'::text,'fait'::text,'a fait'::text,'Super fête, évidemment : elle a fait douze cupcakes sucrés pour zéro invité.'::text),
(321479,35720,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika parti tabii: sıfır misafir için on iki tatlı cupcake ...'::text,'yaptı'::text,'yapar'::text,'yaptı'::text,'Harika parti tabii: sıfır misafir için on iki tatlı cupcake yaptı.'::text),
(321480,35720,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szuper buli, persze: ... tizenkét édes cupcake-et nulla vendégnek.'::text,'sütött'::text,'süt'::text,'sütött'::text,'Szuper buli, persze: sütött tizenkét édes cupcake-et nulla vendégnek.'::text),
(321483,35721,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Riesiger Andrang, klar. Gestern ... niemand wegen ihrer süßen Cupcakes.'::text,'kam'::text,'kommt'::text,NULL::text,'Riesiger Andrang, klar. Gestern kam niemand wegen ihrer süßen Cupcakes.'::text),
(321487,35721,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Величезний натовп, аякже. Учора ніхто не ... по її солодкі капкейки.'::text,'прийшов'::text,'приходить'::text,NULL::text,'Величезний натовп, аякже. Учора ніхто не прийшов по її солодкі капкейки.'::text),
(321486,35721,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una multitud enorme, claro. Ayer nadie ... por sus cupcakes dulces.'::text,'vino'::text,'viene'::text,NULL::text,'Una multitud enorme, claro. Ayer nadie vino por sus cupcakes dulces.'::text),
(321485,35721,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une foule énorme, clairement. Hier, personne ... pour ses cupcakes sucrés.'::text,'n''est venu'::text,'ne vient'::text,NULL::text,'Une foule énorme, clairement. Hier, personne n''est venu pour ses cupcakes sucrés.'::text),
(321488,35721,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev bir kalabalık, belli. Dün onun tatlı cupcake''leri için kimse ...'::text,'gelmedi'::text,'gelmez'::text,NULL::text,'Dev bir kalabalık, belli. Dün onun tatlı cupcake''leri için kimse gelmedi.'::text),
(321489,35721,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Óriási tömeg, egyértelműen. Tegnap senki sem ... el az édes cupcake-jeiért.'::text,'jött'::text,'jön'::text,NULL::text,'Óriási tömeg, egyértelműen. Tegnap senki sem jött el az édes cupcake-jeiért.'::text),
(321492,35722,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jetzt ein Tablett mit süßen Cupcakes auf die Terrasse.'::text,'trägt'::text,'trägt'::text,'trägt'::text,'Sie trägt jetzt ein Tablett mit süßen Cupcakes auf die Terrasse.'::text),
(321496,35722,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона зараз ... тацю з солодкими капкейками на терасу.'::text,'несе'::text,'несе'::text,'несе'::text,'Вона зараз несе тацю з солодкими капкейками на терасу.'::text),
(321495,35722,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora ella ... una bandeja de cupcakes dulces a la terraza.'::text,'está llevando'::text,'lleva'::text,'está llevando'::text,'Ahora ella está llevando una bandeja de cupcakes dulces a la terraza.'::text),
(321494,35722,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... un plateau de cupcakes sucrés sur la terrasse maintenant.'::text,'est en train de porter'::text,'porte'::text,'est en train de porter'::text,'Elle est en train de porter un plateau de cupcakes sucrés sur la terrasse maintenant.'::text),
(321497,35722,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdi terasa bir tepsi tatlı cupcake ...'::text,'taşıyor'::text,'taşır'::text,'taşıyor'::text,'Şimdi terasa bir tepsi tatlı cupcake taşıyor.'::text),
(321498,35722,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most egy tálca édes cupcake-et ... ki a teraszra.'::text,'visz'::text,'visz'::text,'visz'::text,'Most egy tálca édes cupcake-et visz ki a teraszra.'::text),
(321510,35724,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Cupcakes sind süß, also ... sie morgen auch süß sein.'::text,'werden'::text,'sind'::text,'war'::text,'Die Cupcakes sind süß, also werden sie morgen auch süß sein.'::text),
(321514,35724,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Капкейки солодкі, тож вони ... солодкими й завтра.'::text,'будуть'::text,'є'::text,'був'::text,'Капкейки солодкі, тож вони будуть солодкими й завтра.'::text),
(321513,35724,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los cupcakes son dulces, así que mañana también ... dulces.'::text,'serán'::text,'son'::text,'era'::text,'Los cupcakes son dulces, así que mañana también serán dulces.'::text),
(321512,35724,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les cupcakes sont sucrés, donc ils ... sucrés demain aussi.'::text,'seront'::text,'sont'::text,'était'::text,'Les cupcakes sont sucrés, donc ils seront sucrés demain aussi.'::text),
(321515,35724,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cupcake''ler tatlı, yani yarın da tatlı ...'::text,'olacaklar'::text,NULL::text,'idi'::text,'Cupcake''ler tatlı, yani yarın da tatlı olacaklar.'::text),
(321516,35724,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A cupcake-ek édesek, szóval holnap is édesek ...'::text,'lesznek'::text,NULL::text,'volt'::text,'A cupcake-ek édesek, szóval holnap is édesek lesznek.'::text),
(321519,35725,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, deine Cupcakes sehen ... aus als jeder Kuchen in der Stadt.'::text,'süßer'::text,'süßer'::text,'am süßesten'::text,'Ehrlich gesagt, deine Cupcakes sehen süßer aus als jeder Kuchen in der Stadt.'::text),
(321523,35725,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, твої капкейки виглядають ... за будь-який торт у місті.'::text,'солодшими'::text,'більш солодкими'::text,'найсолодшими'::text,'Не буду брехати, твої капкейки виглядають солодшими за будь-який торт у місті.'::text),
(321522,35725,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, tus cupcakes parecen ... que cualquier tarta de la ciudad.'::text,'más dulces'::text,'más dulces'::text,'los más dulces'::text,'No voy a mentir, tus cupcakes parecen más dulces que cualquier tarta de la ciudad.'::text),
(321521,35725,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tes cupcakes ont l''air ... que n''importe quel gâteau en ville.'::text,'plus sucrés'::text,'plus sucrés'::text,'les plus sucrés'::text,'Je vais pas mentir, tes cupcakes ont l''air plus sucrés que n''importe quel gâteau en ville.'::text),
(321524,35725,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, cupcake''lerin şehirdeki her pastadan ... görünüyor.'::text,'daha tatlı'::text,'daha tatlı'::text,'en tatlı'::text,'Yalan yok, cupcake''lerin şehirdeki her pastadan daha tatlı görünüyor.'::text),
(321525,35725,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, a cupcake-jeid ... néznek ki, mint bármelyik torta a városban.'::text,'édesebbnek'::text,'édesebbnek'::text,'legédesebbnek'::text,'Nem hazudok, a cupcake-jeid édesebbnek néznek ki, mint bármelyik torta a városban.'::text),
(321528,35726,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Du trägst die süßen Cupcakes so ...'::text,'vorsichtig.'::text,'vorsichtig.'::text,'vorsichtig.'::text,'Respekt: Du trägst die süßen Cupcakes so vorsichtig.'::text),
(321532,35726,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: ти несеш ці солодкі капкейки так ...'::text,'обережно.'::text,'обережний.'::text,'обережно.'::text,'Респект: ти несеш ці солодкі капкейки так обережно.'::text),
(321531,35726,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: llevas los cupcakes dulces tan ...'::text,'cuidadosamente.'::text,'cuidadoso.'::text,'cuidadosamente.'::text,'Respeto: llevas los cupcakes dulces tan cuidadosamente.'::text),
(321530,35726,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : tu portes les cupcakes sucrés si ...'::text,'soigneusement.'::text,'soigneux.'::text,'soigneusement.'::text,'Respect : tu portes les cupcakes sucrés si soigneusement.'::text),
(321533,35726,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal: tatlı cupcake''leri öyle ... taşıyorsun.'::text,'dikkatlice'::text,'dikkatli'::text,'dikkatlice'::text,'Helal: tatlı cupcake''leri öyle dikkatlice taşıyorsun.'::text),
(321534,35726,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: olyan ... viszed az édes cupcake-eket.'::text,'óvatosan'::text,'óvatos'::text,'óvatosan'::text,'Respekt: olyan óvatosan viszed az édes cupcake-eket.'::text),
(320484,35610,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hilfe! Sie ... jedes Bein des Insekts mit ihrer Lupe untersuchen!'::text,'kann'::text,'kann'::text,'kann'::text,'Hilfe! Sie kann jedes Bein des Insekts mit ihrer Lupe untersuchen!'::text),
(320488,35610,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рятуйте! Вона ... розглядати кожну лапку комахи своєю лупою!'::text,'може'::text,'може'::text,'може'::text,'Рятуйте! Вона може розглядати кожну лапку комахи своєю лупою!'::text),
(320487,35610,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Socorro! ¡Ella ... examinar cada pata del insecto con su lupa!'::text,'puede'::text,'puede'::text,'puede'::text,'¡Socorro! ¡Ella puede examinar cada pata del insecto con su lupa!'::text),
(320486,35610,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au secours ! Elle ... examiner chaque patte de l''insecte avec sa loupe !'::text,'peut'::text,'peut'::text,'peut'::text,'Au secours ! Elle peut examiner chaque patte de l''insecte avec sa loupe !'::text),
(320489,35610,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İmdat! Büyüteciyle böceğin her bacağını ...!'::text,'inceleyebilir'::text,'inceleyebilir'::text,'inceleyebilir'::text,'İmdat! Büyüteciyle böceğin her bacağını inceleyebilir!'::text),
(320490,35610,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Segítség! A nagyítójával ... a rovar minden lábát!'::text,'megvizsgálhatja'::text,'megvizsgálhatja'::text,'megvizsgálhatja'::text,'Segítség! A nagyítójával megvizsgálhatja a rovar minden lábát!'::text),
(320493,35611,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... untersucht sie das Insekt? Mit einer Lupe.'::text,'Wie'::text,'Wer'::text,'Wo'::text,'Wie untersucht sie das Insekt? Mit einer Lupe.'::text),
(320497,35611,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вона розглядає комаху? Лупою.'::text,'Як'::text,'Хто'::text,'Де'::text,'Як вона розглядає комаху? Лупою.'::text),
(320496,35611,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... examina ella el insecto? Con una lupa.'::text,'Cómo'::text,'Quién'::text,'Dónde'::text,'¿Cómo examina ella el insecto? Con una lupa.'::text),
(320495,35611,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... examine-t-elle l''insecte ? Avec une loupe.'::text,'Comment'::text,'Qui'::text,'Où'::text,'Comment examine-t-elle l''insecte ? Avec une loupe.'::text),
(320498,35611,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Böceği ... inceliyor? Büyüteçle.'::text,'nasıl'::text,'kim'::text,'nerede'::text,'Böceği nasıl inceliyor? Büyüteçle.'::text),
(320499,35611,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... vizsgálja a rovart? Nagyítóval.'::text,'Hogyan'::text,'Ki'::text,'Hol'::text,'Hogyan vizsgálja a rovart? Nagyítóval.'::text),
(320502,35612,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich ... sie jedes Insekt auf der Wiese untersuchen.'::text,'wird'::text,'wird'::text,'werden'::text,'Hör mal, angeblich wird sie jedes Insekt auf der Wiese untersuchen.'::text),
(320506,35612,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона ... дослідити кожну комаху на лузі.'::text,'збирається'::text,'збирається'::text,'збираються'::text,'Слухай, кажуть, вона збирається дослідити кожну комаху на лузі.'::text),
(320505,35612,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ella ... estudiar cada insecto del prado.'::text,'va a'::text,'va a'::text,'van a'::text,'Oye, al parecer ella va a estudiar cada insecto del prado.'::text),
(320504,35612,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle ... étudier chaque insecte du pré.'::text,'va'::text,'va'::text,'vont'::text,'Écoute, apparemment elle va étudier chaque insecte du pré.'::text),
(320507,35612,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre çayırdaki her böceği ...'::text,'inceleyecek'::text,'inceleyecek'::text,'inceleyecekler'::text,'Dinle, duyduğuma göre çayırdaki her böceği inceleyecek.'::text),
(320508,35612,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a rét minden rovarát meg ... vizsgálni.'::text,'fogja'::text,'fogja'::text,'fogják'::text,'Figyelj, állítólag a rét minden rovarát meg fogja vizsgálni.'::text),
(320511,35613,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, Lupe raus! Sie ... den Käfer untersuchen, echt jetzt.'::text,'wird'::text,'wird'::text,NULL::text,'Yo, Lupe raus! Sie wird den Käfer untersuchen, echt jetzt.'::text),
(320515,35613,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, лупу в руки! Вона ... цього жука, реально.'::text,'збирається дослідити'::text,'дослідить'::text,NULL::text,'Йо, лупу в руки! Вона збирається дослідити цього жука, реально.'::text),
(320514,35613,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Eh, lupa en mano! Ella ... ese bicho, en serio.'::text,'va a estudiar'::text,'estudiará'::text,NULL::text,'¡Eh, lupa en mano! Ella va a estudiar ese bicho, en serio.'::text),
(320513,35613,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, loupe dégainée ! Elle ... cette bestiole, sérieux.'::text,'va étudier'::text,'étudiera'::text,NULL::text,'Yo, loupe dégainée ! Elle va étudier cette bestiole, sérieux.'::text),
(320516,35613,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, büyüteç hazır! O böceği ..., cidden.'::text,'inceleyecek'::text,'inceleyecek'::text,NULL::text,'Kanka, büyüteç hazır! O böceği inceleyecek, cidden.'::text),
(320517,35613,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, elő a nagyítót! Azt a bogarat ..., komolyan.'::text,'meg fogja vizsgálni'::text,'meg fogja vizsgálni'::text,NULL::text,'Figyu, elő a nagyítót! Azt a bogarat meg fogja vizsgálni, komolyan.'::text),
(320520,35614,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Für ihren Biounterricht ... sie ein Insekt untersuchen und es zeichnen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Für ihren Biounterricht muss sie ein Insekt untersuchen und es zeichnen.'::text),
(320524,35614,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Для уроку біології вона ... дослідити одну комаху й намалювати її.'::text,'має'::text,'мусить'::text,'мала б'::text,'Для уроку біології вона має дослідити одну комаху й намалювати її.'::text),
(320523,35614,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para su clase de biología, ella ... estudiar un insecto y dibujarlo.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Para su clase de biología, ella tiene que estudiar un insecto y dibujarlo.'::text),
(320522,35614,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pour son cours de bio, elle ... étudier un insecte et le dessiner.'::text,'doit'::text,'doit'::text,'devrait'::text,'Pour son cours de bio, elle doit étudier un insecte et le dessiner.'::text),
(320525,35614,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biyoloji dersi için bir böceği ...'::text,'inceleyip çizmek zorunda'::text,'inceleyip çizmeli'::text,'inceleyip çizmeli'::text,'Biyoloji dersi için bir böceği inceleyip çizmek zorunda.'::text),
(320526,35614,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A biológiaórájára ... megvizsgálnia egy rovart, és lerajzolnia.'::text,'kell'::text,'kell'::text,'kellene'::text,'A biológiaórájára kell megvizsgálnia egy rovart, és lerajzolnia.'::text),
(320538,35616,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Total entspannt, eh klar: Sie untersucht den Käfer, ... sie eine perfekte Skizze will.'::text,'weil'::text,'aber'::text,'also'::text,'Total entspannt, eh klar: Sie untersucht den Käfer, weil sie eine perfekte Skizze will.'::text),
(320542,35616,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже невимушено, звісно: вона розглядає жука, ... хоче ідеальний ескіз.'::text,'бо'::text,'але'::text,'тому'::text,'Дуже невимушено, звісно: вона розглядає жука, бо хоче ідеальний ескіз.'::text),
(320541,35616,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Súper relajada, claro: estudia el bicho ... quiere un boceto perfecto.'::text,'porque'::text,'pero'::text,'así que'::text,'Súper relajada, claro: estudia el bicho porque quiere un boceto perfecto.'::text),
(320540,35616,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très détendue, évidemment : elle étudie la bestiole ... elle veut un croquis parfait.'::text,'parce qu'''::text,'mais'::text,'donc'::text,'Très détendue, évidemment : elle étudie la bestiole parce qu'' elle veut un croquis parfait.'::text),
(320543,35616,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gayet rahat, belli: böceği inceliyor ... mükemmel bir eskiz istiyor.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Gayet rahat, belli: böceği inceliyor çünkü mükemmel bir eskiz istiyor.'::text),
(320544,35616,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljesen laza, persze: vizsgálja a bogarat, ... tökéletes vázlatot akar.'::text,'mert'::text,'de'::text,'ezért'::text,'Teljesen laza, persze: vizsgálja a bogarat, mert tökéletes vázlatot akar.'::text),
(307254,34140,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... die große Balkontür mit beiden Armen öffnen.'::text,'kann'::text,'kann'::text,'ist'::text,'Der Mann kann die große Balkontür mit beiden Armen öffnen.'::text),
(307258,34140,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... відчинити великі балконні двері обома руками.'::text,'може'::text,'може'::text,'є'::text,'Чоловік може відчинити великі балконні двері обома руками.'::text),
(307257,34140,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... abrir las grandes puertas del balcón con los dos brazos.'::text,'puede'::text,'puede'::text,'está'::text,'El hombre puede abrir las grandes puertas del balcón con los dos brazos.'::text),
(307256,34140,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... ouvrir les grandes portes du balcon avec ses deux bras.'::text,'peut'::text,'peut'::text,'est'::text,'L''homme peut ouvrir les grandes portes du balcon avec ses deux bras.'::text),
(307259,34140,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam büyük balkon kapılarını iki koluyla ...'::text,'açabilir'::text,'açabilir'::text,NULL::text,'Adam büyük balkon kapılarını iki koluyla açabilir.'::text),
(307260,34140,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi mindkét karjával ... a nagy erkélyajtókat.'::text,'kinyithatja'::text,'kinyithatja'::text,'van'::text,'A férfi mindkét karjával kinyithatja a nagy erkélyajtókat.'::text),
(307263,34141,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, ... macht er jedes Fenster auf? Muss da drin heiß sein.'::text,'warum'::text,'wer'::text,'was'::text,'Nee, warum macht er jedes Fenster auf? Muss da drin heiß sein.'::text),
(307267,34141,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, ... він відчиняє кожне вікно? Там, мабуть, спекотно.'::text,'чому'::text,'хто'::text,'що'::text,'Не, чому він відчиняє кожне вікно? Там, мабуть, спекотно.'::text),
(307266,34141,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ver, ¿... abre todas las ventanas? Debe de hacer calor ahí dentro.'::text,'por qué'::text,'quién'::text,'qué'::text,'A ver, ¿por qué abre todas las ventanas? Debe de hacer calor ahí dentro.'::text),
(307265,34141,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non mais, ... il ouvre toutes les fenêtres ? Il doit faire chaud là-dedans.'::text,'pourquoi'::text,'qui'::text,'quoi'::text,'Non mais, pourquoi il ouvre toutes les fenêtres ? Il doit faire chaud là-dedans.'::text),
(307268,34141,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok artık, ... her pencereyi açıyor? İçerisi sıcak olmalı.'::text,'neden'::text,'kim'::text,'ne'::text,'Yok artık, neden her pencereyi açıyor? İçerisi sıcak olmalı.'::text),
(307269,34141,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Na, ... nyit ki minden ablakot? Biztos meleg van odabent.'::text,'miért'::text,'ki'::text,'mit'::text,'Na, miért nyit ki minden ablakot? Biztos meleg van odabent.'::text),
(307272,34142,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, er ... jedes Fenster in der Wohnung, irgendwie ikonisch.'::text,'öffnete'::text,'öffnet'::text,'öffnete'::text,'Yo, er öffnete jedes Fenster in der Wohnung, irgendwie ikonisch.'::text),
(307276,34142,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, він ... кожне вікно в квартирі, якось культово.'::text,'відчинив'::text,'відчиняє'::text,'відчинив'::text,'Йо, він відчинив кожне вікно в квартирі, якось культово.'::text),
(307275,34142,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ... todas las ventanas del piso, bastante icónico.'::text,'abrió'::text,'abre'::text,'abrió'::text,'Tío, él abrió todas las ventanas del piso, bastante icónico.'::text),
(307274,34142,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, il ... toutes les fenêtres de l''appart, assez iconique.'::text,'a ouvert'::text,'ouvre'::text,'a ouvert'::text,'Yo, il a ouvert toutes les fenêtres de l''appart, assez iconique.'::text),
(307277,34142,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, evdeki her pencereyi ..., bayağı ikonik.'::text,'açtı'::text,'açar'::text,'açtı'::text,'Kanka, evdeki her pencereyi açtı, bayağı ikonik.'::text),
(307278,34142,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ... a lakás összes ablakát, elég ikonikus.'::text,'kinyitotta'::text,'kinyitja'::text,'kinyitotta'::text,'Figyu, kinyitotta a lakás összes ablakát, elég ikonikus.'::text),
(307281,34143,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise öffnet er ein Fenster, aber gestern ... er alle.'::text,'öffnete'::text,'öffnet'::text,NULL::text,'Normalerweise öffnet er ein Fenster, aber gestern öffnete er alle.'::text),
(307285,34143,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай він відчиняє одне вікно, але вчора ... всі.'::text,'відчинив'::text,'відчиняє'::text,NULL::text,'Зазвичай він відчиняє одне вікно, але вчора відчинив всі.'::text),
(307284,34143,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente abre una ventana, pero ayer ... todas.'::text,'abrió'::text,'abre'::text,NULL::text,'Normalmente abre una ventana, pero ayer abrió todas.'::text),
(307283,34143,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, il ouvre une fenêtre, mais hier il les ... toutes.'::text,'a ouvertes'::text,'ouvre'::text,NULL::text,'D''habitude, il ouvre une fenêtre, mais hier il les a ouvertes toutes.'::text),
(307286,34143,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde bir pencere açar ama dün hepsini ...'::text,'açtı'::text,'açar'::text,NULL::text,'Genelde bir pencere açar ama dün hepsini açtı.'::text),
(307287,34143,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában egy ablakot nyit ki, de tegnap mindet ...'::text,'kinyitotta'::text,'kinyitja'::text,NULL::text,'Általában egy ablakot nyit ki, de tegnap mindet kinyitotta.'::text),
(307299,34145,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Wohnung ist ein Albtraum! Du ... die Fenster öffnen!'::text,'solltest'::text,'sollst'::text,'solltest'::text,'Diese Wohnung ist ein Albtraum! Du solltest die Fenster öffnen!'::text),
(307303,34145,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця квартира — жах! Ти ... відчинити вікна!'::text,'мав би'::text,'будеш'::text,'мав би'::text,'Ця квартира — жах! Ти мав би відчинити вікна!'::text),
(307302,34145,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este piso es una pesadilla! ¡... abrir las ventanas!'::text,'Deberías'::text,'Deberás'::text,'Deberías'::text,'¡Este piso es una pesadilla! ¡Deberías abrir las ventanas!'::text),
(307301,34145,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cet appart est un cauchemar ! Tu ... ouvrir les fenêtres !'::text,'devrais'::text,'devras'::text,'devrais'::text,'Cet appart est un cauchemar ! Tu devrais ouvrir les fenêtres !'::text),
(307304,34145,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu ev tam bir kabus! Pencereleri ...!'::text,'açmalısın'::text,'açacaksın'::text,'açmalısın'::text,'Bu ev tam bir kabus! Pencereleri açmalısın!'::text),
(307305,34145,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a lakás egy rémálom! Ki ... nyitnod az ablakokat!'::text,'kellene'::text,'kell'::text,'kellene'::text,'Ez a lakás egy rémálom! Ki kellene nyitnod az ablakokat!'::text),
(307308,34146,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wohnung war dunkel, ... öffnete er alles! Licht für immer!'::text,'also'::text,'weil'::text,'aber'::text,'Die Wohnung war dunkel, also öffnete er alles! Licht für immer!'::text),
(307312,34146,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Квартира була темна, ... він відчинив усе! Світло назавжди!'::text,'тому'::text,'бо'::text,'але'::text,'Квартира була темна, тому він відчинив усе! Світло назавжди!'::text),
(307311,34146,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El piso estaba oscuro, ¡... lo abrió todo! ¡Luz para siempre!'::text,'así que'::text,'porque'::text,'pero'::text,'El piso estaba oscuro, ¡así que lo abrió todo! ¡Luz para siempre!'::text),
(307310,34146,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''appart était sombre, ... il a tout ouvert ! De la lumière pour toujours !'::text,'donc'::text,'parce qu'''::text,'mais'::text,'L''appart était sombre, donc il a tout ouvert ! De la lumière pour toujours !'::text),
(307313,34146,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev karanlıktı, ... her şeyi açtı! Sonsuza dek ışık!'::text,'bu yüzden'::text,'çünkü'::text,'ama'::text,'Ev karanlıktı, bu yüzden her şeyi açtı! Sonsuza dek ışık!'::text),
(307314,34146,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lakás sötét volt, ... mindent kinyitott! Fény örökre!'::text,'ezért'::text,'mert'::text,'de'::text,'A lakás sötét volt, ezért mindent kinyitott! Fény örökre!'::text),
(321051,35673,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonnenlicht kommt durch ... herein, weil eine Wohnung Fenster hat.'::text,'2 Fenster'::text,'2 Fenster'::text,'2 Fenster'::text,'Sonnenlicht kommt durch 2 Fenster herein, weil eine Wohnung Fenster hat.'::text),
(321055,35673,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сонячне світло проходить крізь ..., бо в квартирі є вікна.'::text,'2 вікна'::text,'2 вікно'::text,'2 вікна'::text,'Сонячне світло проходить крізь 2 вікна, бо в квартирі є вікна.'::text),
(321054,35673,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La luz del sol entra por ... porque un piso tiene ventanas.'::text,'2 ventanas'::text,'2 ventana'::text,'2 ventanas'::text,'La luz del sol entra por 2 ventanas porque un piso tiene ventanas.'::text),
(321053,35673,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lumière du soleil entre par ... parce qu''un appart a des fenêtres.'::text,'2 fenêtres'::text,'2 fenêtre'::text,'2 fenêtres'::text,'La lumière du soleil entre par 2 fenêtres parce qu''un appart a des fenêtres.'::text),
(321056,35673,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş ışığı ... içeri giriyor çünkü bir evin pencereleri vardır.'::text,'2 pencereden'::text,'2 pencereden'::text,'2 pencerelerden'::text,'Güneş ışığı 2 pencereden içeri giriyor çünkü bir evin pencereleri vardır.'::text),
(321057,35673,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A napfény ... jön be, mert egy lakásnak vannak ablakai.'::text,'2 ablakon'::text,'2 ablakon'::text,'2 ablakon'::text,'A napfény 2 ablakon jön be, mert egy lakásnak vannak ablakai.'::text),
(321060,35674,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Sonne steht tief, und ... Sonnenlicht ist warm auf seinem Gesicht.'::text,'das'::text,'ein'::text,'ein'::text,'Die Sonne steht tief, und das Sonnenlicht ist warm auf seinem Gesicht.'::text),
(321064,35674,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сонце низько, і ... сонячне світло тепле на його обличчі.'::text,''::text,NULL::text,NULL::text,'Сонце низько, і сонячне світло тепле на його обличчі.'::text),
(321063,35674,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sol está bajo, y ... luz del sol es cálida en su cara.'::text,'la'::text,'una'::text,'una'::text,'El sol está bajo, y la luz del sol es cálida en su cara.'::text),
(321062,35674,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le soleil est bas, et ... lumière du soleil est chaude sur son visage.'::text,'la'::text,'une'::text,'une'::text,'Le soleil est bas, et la lumière du soleil est chaude sur son visage.'::text),
(321065,35674,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş alçakta ve ... güneş ışığı yüzünde sıcak.'::text,''::text,'bir'::text,'bir'::text,'Güneş alçakta ve güneş ışığı yüzünde sıcak.'::text),
(321066,35674,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alacsonyan van a nap, és ... napfény meleg az arcán.'::text,'a'::text,'egy'::text,'egy'::text,'Alacsonyan van a nap, és a napfény meleg az arcán.'::text),
(321069,35675,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Sonnenlicht auf dem Boden ist sehr hell.'::text,'Dieses'::text,'Diese'::text,'Jene'::text,'Dieses Sonnenlicht auf dem Boden ist sehr hell.'::text),
(321073,35675,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... сонячне світло на підлозі дуже яскраве.'::text,'Це'::text,'Ці'::text,'Ті'::text,'Це сонячне світло на підлозі дуже яскраве.'::text),
(321072,35675,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... luz del sol en el suelo es muy intensa.'::text,'Esta'::text,'Estas'::text,'Esas'::text,'Esta luz del sol en el suelo es muy intensa.'::text),
(321071,35675,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... lumière du soleil sur le sol est très vive.'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette lumière du soleil sur le sol est très vive.'::text),
(321074,35675,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yerdeki ... güneş ışığı çok parlak.'::text,'bu'::text,'bu'::text,'şu'::text,'Yerdeki bu güneş ışığı çok parlak.'::text),
(321075,35675,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a napfény a padlón nagyon erős.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a napfény a padlón nagyon erős.'::text),
(321078,35676,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er öffnet ... Fenster und lässt das Sonnenlicht herein.'::text,'seine'::text,'ihre'::text,'seine'::text,'Er öffnet seine Fenster und lässt das Sonnenlicht herein.'::text),
(321082,35676,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він відчиняє ... вікна й впускає сонячне світло.'::text,'свої'::text,'свої'::text,'свої'::text,'Він відчиняє свої вікна й впускає сонячне світло.'::text),
(321081,35676,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abre ... ventanas y deja entrar la luz del sol.'::text,'sus'::text,'sus'::text,'sus'::text,'Abre sus ventanas y deja entrar la luz del sol.'::text),
(321080,35676,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ouvre ... fenêtres et laisse entrer la lumière du soleil.'::text,'ses'::text,'ses'::text,'ses'::text,'Il ouvre ses fenêtres et laisse entrer la lumière du soleil.'::text),
(321083,35676,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pencerelerini açıyor ve güneş ışığını içeri alıyor.'::text,'Onun'::text,'Onun'::text,'Onun'::text,'Onun pencerelerini açıyor ve güneş ışığını içeri alıyor.'::text),
(321084,35676,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kinyitja ..., és beengedi a napfényt.'::text,'az ablakait'::text,'az ablakait'::text,'az ablakait'::text,'Kinyitja az ablakait, és beengedi a napfényt.'::text),
(321087,35677,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, er meinte, Sonnenlicht gibt ihm morgens so viel ...'::text,'Energie'::text,'Energie'::text,'eine Energie'::text,'Süße, er meinte, Sonnenlicht gibt ihm morgens so viel Energie.'::text),
(321091,35677,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав, що сонячне світло дає йому стільки ... зранку.'::text,'енергії'::text,'енергії'::text,'енергії'::text,'Подруго, він сказав, що сонячне світло дає йому стільки енергії зранку.'::text),
(321090,35677,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, dijo que la luz del sol le da tanta ... por la mañana.'::text,'energía'::text,'energía'::text,'una energía'::text,'Tía, dijo que la luz del sol le da tanta energía por la mañana.'::text),
(321089,35677,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il a dit que la lumière du soleil lui donne tellement ... le matin.'::text,'d''énergie'::text,'d''énergie'::text,'d''une énergie'::text,'Meuf, il a dit que la lumière du soleil lui donne tellement d''énergie le matin.'::text),
(321092,35677,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güneş ışığının sabahları ona çok fazla ... verdiğini söyledi.'::text,'enerji'::text,'enerjiler'::text,'bir enerji'::text,'Kızım, güneş ışığının sabahları ona çok fazla enerji verdiğini söyledi.'::text),
(321093,35677,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, a napfény reggelente annyi ... ad neki.'::text,'energiát'::text,'energiát'::text,'egy energiát'::text,'Csajszi, azt mondta, a napfény reggelente annyi energiát ad neki.'::text),
(321105,35679,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, auf diesem Balkon ... so viel Sonnenlicht, ohne Witz.'::text,'ist'::text,'sind'::text,'sein'::text,'Yo, auf diesem Balkon ist so viel Sonnenlicht, ohne Witz.'::text),
(321109,35679,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, на цьому балконі ... стільки сонячного світла, без жартів.'::text,'є'::text,'є'::text,'бути'::text,'Йо, на цьому балконі є стільки сонячного світла, без жартів.'::text),
(321108,35679,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, en este balcón ... tanta luz del sol, en serio.'::text,'hay'::text,'hay'::text,'hay'::text,'Tío, en este balcón hay tanta luz del sol, en serio.'::text),
(321107,35679,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sur ce balcon, ... tellement de lumière du soleil, sans mentir.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Yo, sur ce balcon, il y a tellement de lumière du soleil, sans mentir.'::text),
(321110,35679,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu balkonda o kadar çok güneş ışığı ..., cidden.'::text,'var'::text,'var'::text,'olmak'::text,'Kanka, bu balkonda o kadar çok güneş ışığı var, cidden.'::text),
(321111,35679,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ezen az erkélyen annyi napfény ..., komolyan.'::text,'van'::text,'vannak'::text,'lenni'::text,'Figyu, ezen az erkélyen annyi napfény van, komolyan.'::text),
(318981,35443,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, angeblich ... sie dieses Stück gestern Abend im alten Theater auf.'::text,'führten'::text,'führen'::text,'führten'::text,'Süße, angeblich führten sie dieses Stück gestern Abend im alten Theater auf.'::text),
(318985,35443,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вони ... цю п''єсу в старому театрі вчора ввечері.'::text,'поставили'::text,'ставлять'::text,'поставили'::text,'Подруго, кажуть, вони поставили цю п''єсу в старому театрі вчора ввечері.'::text),
(318984,35443,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer anoche ... esta obra en el teatro antiguo.'::text,'montaron'::text,'montan'::text,'montaron'::text,'Tía, al parecer anoche montaron esta obra en el teatro antiguo.'::text),
(318983,35443,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment ils ... cette pièce dans le vieux théâtre hier soir.'::text,'ont monté'::text,'montent'::text,'ont monté'::text,'Meuf, apparemment ils ont monté cette pièce dans le vieux théâtre hier soir.'::text),
(318986,35443,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre dün akşam bu oyunu eski tiyatroda ...'::text,'sahnelediler'::text,'sahnelerler'::text,'sahnelediler'::text,'Kızım, duyduğuma göre dün akşam bu oyunu eski tiyatroda sahnelediler.'::text),
(318987,35443,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag tegnap este ... ezt a darabot a régi színházban.'::text,'bemutatták'::text,'bemutatják'::text,'bemutatták'::text,'Csajszi, állítólag tegnap este bemutatták ezt a darabot a régi színházban.'::text),
(318990,35444,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal: Normalerweise führen sie Komödien auf, aber gestern ... sie angeblich eine Revolution auf.'::text,'führten'::text,'führen'::text,NULL::text,'Rate mal: Normalerweise führen sie Komödien auf, aber gestern führten sie angeblich eine Revolution auf.'::text),
(318994,35444,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви: зазвичай вони ставлять комедії, але вчора, кажуть, ... революцію.'::text,'поставили'::text,'ставлять'::text,NULL::text,'Уяви: зазвичай вони ставлять комедії, але вчора, кажуть, поставили революцію.'::text),
(318993,35444,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina: normalmente montan comedias, pero ayer, al parecer, ... una revolución.'::text,'montaron'::text,'montan'::text,NULL::text,'Adivina: normalmente montan comedias, pero ayer, al parecer, montaron una revolución.'::text),
(318992,35444,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi : d''habitude ils montent des comédies, mais hier ils ... une révolution, apparemment.'::text,'ont monté'::text,'montent'::text,NULL::text,'Devine quoi : d''habitude ils montent des comédies, mais hier ils ont monté une révolution, apparemment.'::text),
(318995,35444,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et: genelde komedi sahnelerler ama dün bir devrim ..., öyle diyorlar.'::text,'sahnelediler'::text,'sahnelerler'::text,NULL::text,'Tahmin et: genelde komedi sahnelerler ama dün bir devrim sahnelediler, öyle diyorlar.'::text),
(318996,35444,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld: általában vígjátékokat mutatnak be, de tegnap állítólag egy forradalmat ... be.'::text,'mutattak'::text,'mutatnak'::text,NULL::text,'Képzeld: általában vígjátékokat mutatnak be, de tegnap állítólag egy forradalmat mutattak be.'::text),
(318999,35445,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, heute Abend ... ihr dieses Stück wie echte Profis.'::text,'inszeniert'::text,'inszenierend'::text,'inszeniert'::text,'Ehrlich, heute Abend inszeniert ihr dieses Stück wie echte Profis.'::text),
(319003,35445,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, сьогодні ввечері ви ... цю п''єсу як справжні профі.'::text,'ставите'::text,'ставлячи'::text,'ставите'::text,'Чесно, сьогодні ввечері ви ставите цю п''єсу як справжні профі.'::text),
(319002,35445,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, esta noche ... esta obra como auténticos profesionales.'::text,'estáis montando'::text,'montando'::text,'estáis montando'::text,'La verdad, esta noche estáis montando esta obra como auténticos profesionales.'::text),
(319001,35445,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ce soir vous ... cette pièce comme de vrais pros.'::text,'êtes en train de monter'::text,'montant'::text,'êtes en train de monter'::text,'Franchement, ce soir vous êtes en train de monter cette pièce comme de vrais pros.'::text),
(319004,35445,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası bu akşam bu oyunu gerçek profesyoneller gibi ...'::text,'sahneliyorsunuz'::text,'sahneleyerek'::text,'sahneliyorsunuz'::text,'Açıkçası bu akşam bu oyunu gerçek profesyoneller gibi sahneliyorsunuz.'::text),
(319005,35445,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ma este úgy ... ezt a darabot, mint az igazi profik.'::text,'rendezitek'::text,'rendező'::text,'rendezitek'::text,'Őszintén, ma este úgy rendezitek ezt a darabot, mint az igazi profik.'::text),
(319008,35446,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Theater inszeniert normalerweise Komödien, aber heute Abend ... es ein Königsdrama.'::text,'inszeniert'::text,'inszeniert'::text,NULL::text,'Das Theater inszeniert normalerweise Komödien, aber heute Abend inszeniert es ein Königsdrama.'::text),
(319012,35446,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Театр зазвичай ставить комедії, але сьогодні ввечері ... драму про короля.'::text,'ставить'::text,'ставить'::text,NULL::text,'Театр зазвичай ставить комедії, але сьогодні ввечері ставить драму про короля.'::text),
(319011,35446,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El teatro normalmente monta comedias, pero esta noche ... un drama sobre un rey.'::text,'está montando'::text,'monta'::text,NULL::text,'El teatro normalmente monta comedias, pero esta noche está montando un drama sobre un rey.'::text),
(319010,35446,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, le théâtre monte des comédies, mais ce soir il ... un drame royal.'::text,'est en train de monter'::text,'monte'::text,NULL::text,'D''habitude, le théâtre monte des comédies, mais ce soir il est en train de monter un drame royal.'::text),
(319013,35446,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiyatro genelde komedi sahneler ama bu akşam bir kral draması ...'::text,'sahneliyor'::text,'sahneler'::text,NULL::text,'Tiyatro genelde komedi sahneler ama bu akşam bir kral draması sahneliyor.'::text),
(319014,35446,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A színház általában vígjátékokat mutat be, de ma este egy királydrámát ...'::text,'mutat be'::text,'mutat be'::text,NULL::text,'A színház általában vígjátékokat mutat be, de ma este egy királydrámát mutat be.'::text),
(319026,35448,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rache! Nächsten Monat ... sie den Sturz des Königs wieder aufführen!'::text,'werden'::text,'werden'::text,'wird'::text,'Rache! Nächsten Monat werden sie den Sturz des Königs wieder aufführen!'::text),
(319030,35448,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Помста! Наступного місяця вони ... падіння короля знову!'::text,'збираються поставити'::text,'збираються поставити'::text,'збирається поставити'::text,'Помста! Наступного місяця вони збираються поставити падіння короля знову!'::text),
(319029,35448,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Venganza! ¡El mes que viene ... otra vez la caída del rey!'::text,'van a montar'::text,'van a montar'::text,'va a montar'::text,'¡Venganza! ¡El mes que viene van a montar otra vez la caída del rey!'::text),
(319028,35448,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vengeance ! Le mois prochain, ils ... de nouveau la chute du roi !'::text,'vont monter'::text,'vont monter'::text,'va monter'::text,'Vengeance ! Le mois prochain, ils vont monter de nouveau la chute du roi !'::text),
(319031,35448,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İntikam! Gelecek ay kralın düşüşünü yeniden ...!'::text,'sahneleyecekler'::text,'sahneleyecekler'::text,'sahneleyecek'::text,'İntikam! Gelecek ay kralın düşüşünü yeniden sahneleyecekler!'::text),
(319032,35448,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bosszú! Jövő hónapban újra színpadra ... vinni a király bukását!'::text,'fogják'::text,'fogják'::text,'fogja'::text,'Bosszú! Jövő hónapban újra színpadra fogják vinni a király bukását!'::text),
(319035,35449,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie lieben es! Ich verspreche, dass wir dieses Stück für immer wieder ...'::text,'aufführen werden'::text,'aufführen werden'::text,NULL::text,'Sie lieben es! Ich verspreche, dass wir dieses Stück für immer wieder aufführen werden.'::text),
(319039,35449,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їм подобається! Обіцяю, ми ... цю п''єсу знову й знову, назавжди!'::text,'поставимо'::text,'збираємося поставити'::text,NULL::text,'Їм подобається! Обіцяю, ми поставимо цю п''єсу знову й знову, назавжди!'::text),
(319038,35449,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Les encanta! ¡Prometo que ... esta obra una y otra vez para siempre!'::text,'montaremos'::text,'vamos a montar'::text,NULL::text,'¡Les encanta! ¡Prometo que montaremos esta obra una y otra vez para siempre!'::text),
(319037,35449,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils adorent ! Je promets que nous ... cette pièce encore et pour toujours !'::text,'monterons'::text,'allons monter'::text,NULL::text,'Ils adorent ! Je promets que nous monterons cette pièce encore et pour toujours !'::text),
(319040,35449,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bayılıyorlar! Söz veriyorum, bu oyunu sonsuza dek yeniden ...!'::text,'sahneleyeceğiz'::text,'sahneleyeceğiz'::text,NULL::text,'Bayılıyorlar! Söz veriyorum, bu oyunu sonsuza dek yeniden sahneleyeceğiz!'::text),
(319041,35449,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Imádják! Megígérem, hogy ezt a darabot örökké újra színpadra ... vinni!'::text,'fogjuk'::text,'fogjuk'::text,NULL::text,'Imádják! Megígérem, hogy ezt a darabot örökké újra színpadra fogjuk vinni!'::text),
(319044,35450,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also der Regisseur hat mir erzählt, dass die Schauspieler das Stück heute Abend zweimal ...'::text,'aufführen müssen'::text,'aufführen müssen'::text,'aufführen sollten'::text,'Okay, also der Regisseur hat mir erzählt, dass die Schauspieler das Stück heute Abend zweimal aufführen müssen.'::text),
(319048,35450,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, режисер мені сказав, що актори ... зіграти виставу двічі сьогодні ввечері.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Коротше, режисер мені сказав, що актори мають зіграти виставу двічі сьогодні ввечері.'::text),
(319047,35450,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, el director me ha dicho que los actores ... representar la obra dos veces esta noche.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'Vale, el director me ha dicho que los actores tienen que representar la obra dos veces esta noche.'::text),
(319046,35450,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, le metteur en scène m''a dit que les acteurs ... jouer la pièce deux fois ce soir.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Bon alors, le metteur en scène m''a dit que les acteurs doivent jouer la pièce deux fois ce soir.'::text),
(319049,35450,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, yönetmen dedi ki oyuncular bu akşam oyunu iki kez ...'::text,'sahnelemek zorunda'::text,'sahnelemeli'::text,'sahnelemeli'::text,'Tamam, yönetmen dedi ki oyuncular bu akşam oyunu iki kez sahnelemek zorunda.'::text),
(319050,35450,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval a rendező azt mondta, hogy a színészeknek ma este kétszer ... előadniuk a darabot.'::text,'kell'::text,'kell'::text,'kellene'::text,'Oké, szóval a rendező azt mondta, hogy a színészeknek ma este kétszer kell előadniuk a darabot.'::text),
(316344,35150,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich ... meinen Koffer immer, indem ich mich draufsetze.'::text,'schließe'::text,'schließt'::text,'schließend'::text,'Ich schließe meinen Koffer immer, indem ich mich draufsetze.'::text),
(316348,35150,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я завжди ... свою валізу, сідаючи на неї.'::text,'закриваю'::text,'закриває'::text,'закриваючи'::text,'Я завжди закриваю свою валізу, сідаючи на неї.'::text),
(316347,35150,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Siempre ... la maleta sentándome encima.'::text,'cierro'::text,'cierra'::text,'cerrando'::text,'Siempre cierro la maleta sentándome encima.'::text),
(316346,35150,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je ... toujours ma valise en m''asseyant dessus.'::text,'ferme'::text,'ferme'::text,'fermant'::text,'Je ferme toujours ma valise en m''asseyant dessus.'::text),
(316349,35150,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bavulumu hep üstüne oturarak ...'::text,'kapatırım'::text,'kapatır'::text,'kapatarak'::text,'Bavulumu hep üstüne oturarak kapatırım.'::text),
(316350,35150,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindig úgy ... a bőröndömet, hogy ráülök.'::text,'csukom be'::text,'csukja be'::text,'becsukó'::text,'Mindig úgy csukom be a bőröndömet, hogy ráülök.'::text),
(316353,35151,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Koffer ist zu voll, sodass sie den Deckel ...'::text,'nicht zumachen kann'::text,'nicht zumachen kann'::text,'nicht zumachen kann'::text,'Der Koffer ist zu voll, sodass sie den Deckel nicht zumachen kann.'::text),
(316357,35151,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Валіза надто повна, тож вона ... закрити кришку.'::text,'не може'::text,'не може'::text,'не може'::text,'Валіза надто повна, тож вона не може закрити кришку.'::text),
(316356,35151,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maleta está demasiado llena, así que ella ... cerrar la tapa.'::text,'no puede'::text,'no puede'::text,'no puede'::text,'La maleta está demasiado llena, así que ella no puede cerrar la tapa.'::text),
(316355,35151,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La valise est trop pleine, donc elle ... fermer le couvercle.'::text,'ne peut pas'::text,'ne peut pas'::text,'ne peut pas'::text,'La valise est trop pleine, donc elle ne peut pas fermer le couvercle.'::text),
(316358,35151,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bavul çok dolu, bu yüzden kapağı ...'::text,'kapatamaz'::text,'kapatamaz'::text,'kapatamaz'::text,'Bavul çok dolu, bu yüzden kapağı kapatamaz.'::text),
(316359,35151,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bőrönd túl tele van, ezért ... lecsukni a fedelét.'::text,'nem tudja'::text,'nem tudja'::text,'nem tudja'::text,'A bőrönd túl tele van, ezért nem tudja lecsukni a fedelét.'::text),
(316371,35153,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super gepackt, eh klar: Sie ... ihren Koffer mit ihrem ganzen Gewicht.'::text,'schloss'::text,'schloss'::text,'schließt'::text,'Super gepackt, eh klar: Sie schloss ihren Koffer mit ihrem ganzen Gewicht.'::text),
(316375,35153,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудово спакувалася, звісно: вона ... свою валізу всією своєю вагою.'::text,'закрила'::text,'закрила'::text,'закриває'::text,'Чудово спакувалася, звісно: вона закрила свою валізу всією своєю вагою.'::text),
(316374,35153,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué buen equipaje, claro: ella ... la maleta con todo su peso.'::text,'cerró'::text,'cerró'::text,'cierra'::text,'Qué buen equipaje, claro: ella cerró la maleta con todo su peso.'::text),
(316373,35153,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super bagage, évidemment : elle ... sa valise de tout son poids.'::text,'a fermé'::text,'a fermé'::text,'ferme'::text,'Super bagage, évidemment : elle a fermé sa valise de tout son poids.'::text),
(316376,35153,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika toplanmış, belli: bavulunu bütün ağırlığıyla ...'::text,'kapattı'::text,'kapattı'::text,'kapatır'::text,'Harika toplanmış, belli: bavulunu bütün ağırlığıyla kapattı.'::text),
(316377,35153,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szuper pakolás, persze: teljes súlyával ... a bőröndjét.'::text,'csukta be'::text,'csukta be'::text,'csukja be'::text,'Szuper pakolás, persze: teljes súlyával csukta be a bőröndjét.'::text),
(316380,35154,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minimalistisch gepackt, klar. Gestern ... sie ihren Koffer, indem sie sich draufsetzte.'::text,'schloss'::text,'schließt'::text,NULL::text,'Minimalistisch gepackt, klar. Gestern schloss sie ihren Koffer, indem sie sich draufsetzte.'::text),
(316384,35154,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пакується легко, звісно. Учора вона ... валізу, сівши на неї.'::text,'закрила'::text,'закриває'::text,NULL::text,'Пакується легко, звісно. Учора вона закрила валізу, сівши на неї.'::text),
(316383,35154,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Viaja ligera, claro. Ayer ... la maleta sentándose encima.'::text,'cerró'::text,'cierra'::text,NULL::text,'Viaja ligera, claro. Ayer cerró la maleta sentándose encima.'::text),
(316382,35154,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle voyage léger, évidemment. Hier, elle ... sa valise en s''asseyant dessus.'::text,'a fermé'::text,'ferme'::text,NULL::text,'Elle voyage léger, évidemment. Hier, elle a fermé sa valise en s''asseyant dessus.'::text),
(316385,35154,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hafif yolculuk eder, belli. Dün bavulunu üstüne oturarak ...'::text,'kapattı'::text,'kapatır'::text,NULL::text,'Hafif yolculuk eder, belli. Dün bavulunu üstüne oturarak kapattı.'::text),
(316386,35154,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Könnyen pakol, persze. Tegnap úgy ... a bőröndjét, hogy ráült.'::text,'csukta be'::text,'csukja be'::text,NULL::text,'Könnyen pakol, persze. Tegnap úgy csukta be a bőröndjét, hogy ráült.'::text),
(316389,35155,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi: Gerade ... sie den Koffer mit ihrem ganzen Körper.'::text,'schließt'::text,'schließt'::text,'schließt'::text,'Ein echter Profi: Gerade schließt sie den Koffer mit ihrem ganzen Körper.'::text),
(316393,35155,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжня профі: саме зараз вона ... валізу всім тілом.'::text,'закриває'::text,'закриває'::text,'закриває'::text,'Справжня профі: саме зараз вона закриває валізу всім тілом.'::text),
(316392,35155,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toda una profesional: ahora mismo ... la maleta con todo el cuerpo.'::text,'está cerrando'::text,'cierra'::text,'está cerrando'::text,'Toda una profesional: ahora mismo está cerrando la maleta con todo el cuerpo.'::text),
(316391,35155,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une vraie pro : en ce moment, elle ... la valise avec tout son corps.'::text,'est en train de fermer'::text,'ferme'::text,'est en train de fermer'::text,'Une vraie pro : en ce moment, elle est en train de fermer la valise avec tout son corps.'::text),
(316394,35155,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir profesyonel: şu an bavulu bütün vücuduyla ...'::text,'kapatıyor'::text,'kapatır'::text,'kapatıyor'::text,'Tam bir profesyonel: şu an bavulu bütün vücuduyla kapatıyor.'::text),
(316395,35155,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi: épp most az egész testével ... a bőröndöt.'::text,'csukja be'::text,'csukja be'::text,'csukja be'::text,'Igazi profi: épp most az egész testével csukja be a bőröndöt.'::text),
(316407,35157,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sitzt auf dem Deckel, ... er geht immer noch nicht zu! Albtraum!'::text,'aber'::text,'also'::text,'weil'::text,'Sie sitzt auf dem Deckel, aber er geht immer noch nicht zu! Albtraum!'::text),
(316411,35157,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сидить на кришці, ... та все одно не закривається! Жах!'::text,'але'::text,'тому'::text,'бо'::text,'Вона сидить на кришці, але та все одно не закривається! Жах!'::text),
(316410,35157,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está sentada en la tapa, ¡... sigue sin cerrarse! ¡Pesadilla!'::text,'pero'::text,'así que'::text,'porque'::text,'Está sentada en la tapa, ¡pero sigue sin cerrarse! ¡Pesadilla!'::text),
(316409,35157,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est assise sur le couvercle, ... ça ne ferme toujours pas ! Cauchemar !'::text,'mais'::text,'donc'::text,'parce que'::text,'Elle est assise sur le couvercle, mais ça ne ferme toujours pas ! Cauchemar !'::text),
(316412,35157,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapağın üstüne oturuyor ... hâlâ kapanmıyor! Kabus!'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Kapağın üstüne oturuyor ama hâlâ kapanmıyor! Kabus!'::text),
(316413,35157,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fedelén ül, ... még mindig nem csukódik be! Rémálom!'::text,'de'::text,'ezért'::text,'mert'::text,'A fedelén ül, de még mindig nem csukódik be! Rémálom!'::text),
(300792,33422,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... eine schlimme Verletzung am Bein.'::text,'hat'::text,'haben'::text,'hat'::text,'Er hat eine schlimme Verletzung am Bein.'::text),
(300796,33422,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... серйозну травму на нозі.'::text,'має'::text,'мати'::text,'має'::text,'Він має серйозну травму на нозі.'::text),
(300795,33422,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... una herida fea en la pierna.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'Él tiene una herida fea en la pierna.'::text),
(300794,33422,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... une vilaine blessure à la jambe.'::text,'a'::text,'ont'::text,'a'::text,'Il a une vilaine blessure à la jambe.'::text),
(300797,33422,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bacağında kötü bir yarası ...'::text,'var'::text,'var'::text,'var'::text,'Bacağında kötü bir yarası var.'::text),
(300798,33422,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lábán csúnya sérülés ...'::text,'van'::text,'van'::text,'van'::text,'A lábán csúnya sérülés van.'::text),
(300801,33423,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Verletzung ist an einem Bein, nicht an zwei ...'::text,'Beinen'::text,'Bein'::text,'Beinen'::text,'Die Verletzung ist an einem Bein, nicht an zwei Beinen.'::text),
(300805,33423,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Травма на одній нозі, а не на двох ...'::text,'ногах'::text,'нозі'::text,'ногах'::text,'Травма на одній нозі, а не на двох ногах.'::text),
(300804,33423,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La herida está en una pierna, no en dos ...'::text,'piernas'::text,'pierna'::text,'piernas'::text,'La herida está en una pierna, no en dos piernas.'::text),
(300803,33423,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La blessure est sur une jambe, pas sur deux ...'::text,'jambes'::text,'jambe'::text,'jambes'::text,'La blessure est sur une jambe, pas sur deux jambes.'::text),
(300806,33423,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yara tek bacakta, iki ... değil.'::text,'bacakta'::text,'bacakta'::text,'bacaklarda'::text,'Yara tek bacakta, iki bacakta değil.'::text),
(300807,33423,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sérülés az egyik lábán van, nem két ...'::text,'lábán'::text,'lábán'::text,'lábán'::text,'A sérülés az egyik lábán van, nem két lábán.'::text),
(300810,33424,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat eine Verletzung am Bein, und ... Verletzung ist schlimm.'::text,'die'::text,'eine'::text,'eine'::text,'Er hat eine Verletzung am Bein, und die Verletzung ist schlimm.'::text),
(300814,33424,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У нього травма на нозі, і ... травма серйозна.'::text,''::text,NULL::text,NULL::text,'У нього травма на нозі, і травма серйозна.'::text),
(300813,33424,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene una herida en la pierna, y ... herida es fea.'::text,'la'::text,'una'::text,'una'::text,'Tiene una herida en la pierna, y la herida es fea.'::text),
(300812,33424,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a une blessure à la jambe, et ... blessure est grave.'::text,'la'::text,'une'::text,'une'::text,'Il a une blessure à la jambe, et la blessure est grave.'::text),
(300815,33424,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bacağında bir yara var ve ... yara kötü.'::text,''::text,'bir'::text,'bir'::text,'Bacağında bir yara var ve yara kötü.'::text),
(300816,33424,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Van egy sérülés a lábán, és ... sérülés csúnya.'::text,'a'::text,'egy'::text,'egy'::text,'Van egy sérülés a lábán, és a sérülés csúnya.'::text),
(300819,33425,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Verletzung an seinem Schienbein ist vom Sofa.'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Diese Verletzung an seinem Schienbein ist vom Sofa.'::text),
(300823,33425,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... травма на його гомілці — від дивана.'::text,'Ця'::text,'Ці'::text,'Ті'::text,'Ця травма на його гомілці — від дивана.'::text),
(300822,33425,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... herida de la espinilla es del sofá.'::text,'Esta'::text,'Estas'::text,'Esas'::text,'Esta herida de la espinilla es del sofá.'::text),
(300821,33425,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... blessure au tibia vient du canapé.'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette blessure au tibia vient du canapé.'::text),
(300824,33425,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaval kemiğindeki ... yara kanepeden.'::text,'bu'::text,'bu'::text,'şu'::text,'Kaval kemiğindeki bu yara kanepeden.'::text),
(300825,33425,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a sérülés a sípcsontján a kanapétól van.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a sérülés a sípcsontján a kanapétól van.'::text),
(300828,33426,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Sofa hat ihm diese Verletzung verpasst! ... Bein ist hinüber!'::text,'Sein'::text,'Ihr'::text,'Unser'::text,'Das Sofa hat ihm diese Verletzung verpasst! Sein Bein ist hinüber!'::text),
(300832,33426,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Диван завдав йому цієї травми! ... нога розбита!'::text,'Його'::text,'Її'::text,'Наша'::text,'Диван завдав йому цієї травми! Його нога розбита!'::text),
(300831,33426,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El sofá le hizo esta herida! ¡... pierna está destrozada!'::text,'Su'::text,'Su'::text,'Nuestra'::text,'¡El sofá le hizo esta herida! ¡Su pierna está destrozada!'::text),
(300830,33426,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le canapé lui a fait cette blessure ! ... jambe est détruite !'::text,'Sa'::text,'Sa'::text,'Notre'::text,'Le canapé lui a fait cette blessure ! Sa jambe est détruite !'::text),
(300833,33426,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yarayı ona kanepe yaptı! ... bacağı mahvoldu!'::text,'Onun'::text,'Onun'::text,'Bizim'::text,'Bu yarayı ona kanepe yaptı! Onun bacağı mahvoldu!'::text),
(300834,33426,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kanapé okozta neki ezt a sérülést! ... tönkrement!'::text,'A lába'::text,'A lába'::text,'A lábunk'::text,'A kanapé okozta neki ezt a sérülést! A lába tönkrement!'::text),
(300837,33427,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sitzt ... dem Boden mit seiner Verletzung! Der schlimmste Tag!'::text,'auf'::text,'in'::text,'an'::text,'Er sitzt auf dem Boden mit seiner Verletzung! Der schlimmste Tag!'::text),
(300841,33427,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сидить ... підлозі зі своєю травмою! Найгірший день!'::text,'на'::text,'у'::text,'біля'::text,'Він сидить на підлозі зі своєю травмою! Найгірший день!'::text),
(300840,33427,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Está sentado ... el suelo con su herida! ¡El peor día!'::text,'en'::text,'en'::text,'a'::text,'¡Está sentado en el suelo con su herida! ¡El peor día!'::text),
(300839,33427,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est assis ... le sol avec sa blessure ! Le pire jour !'::text,'sur'::text,'dans'::text,'à'::text,'Il est assis sur le sol avec sa blessure ! Le pire jour !'::text),
(300842,33427,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarasıyla yerin ... oturuyor! En kötü gün!'::text,'üstünde'::text,'içinde'::text,NULL::text,'Yarasıyla yerin üstünde oturuyor! En kötü gün!'::text),
(300843,33427,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sérülésével ... ül! A legrosszabb nap!'::text,'a padlón'::text,'a padlóban'::text,'a padlónál'::text,'A sérülésével a padlón ül! A legrosszabb nap!'::text),
(302457,33607,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er lässt nie etwas steigen, aber jetzt ... er einen roten Drachen steigen! Bester Tag überhaupt!'::text,'lässt'::text,'lässt'::text,NULL::text,'Er lässt nie etwas steigen, aber jetzt lässt er einen roten Drachen steigen! Bester Tag überhaupt!'::text),
(302461,33607,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ніколи нічого не запускає, але зараз ... червоного повітряного змія! Найкращий день!'::text,'запускає'::text,'запускає'::text,NULL::text,'Він ніколи нічого не запускає, але зараз запускає червоного повітряного змія! Найкращий день!'::text),
(302460,33607,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca hace volar nada, ¡pero ahora ... una cometa roja! ¡El mejor día de la historia!'::text,'está haciendo volar'::text,'hace volar'::text,NULL::text,'Nunca hace volar nada, ¡pero ahora está haciendo volar una cometa roja! ¡El mejor día de la historia!'::text),
(302459,33607,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne fait jamais rien voler, mais là, il ... un cerf-volant rouge ! Meilleur jour de sa vie !'::text,'est en train de faire voler'::text,'fait voler'::text,NULL::text,'Il ne fait jamais rien voler, mais là, il est en train de faire voler un cerf-volant rouge ! Meilleur jour de sa vie !'::text),
(302462,33607,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiçbir şey uçurmaz ama şimdi kırmızı bir uçurtma ...! Hayatının en güzel günü!'::text,'uçuruyor'::text,'uçurur'::text,NULL::text,'Hiçbir şey uçurmaz ama şimdi kırmızı bir uçurtma uçuruyor! Hayatının en güzel günü!'::text),
(302463,33607,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha semmit nem ereget, de most egy piros sárkányt ...! A valaha volt legjobb nap!'::text,'ereget'::text,'ereget'::text,NULL::text,'Soha semmit nem ereget, de most egy piros sárkányt ereget! A valaha volt legjobb nap!'::text),
(302475,33609,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, er hat mir erzählt, dass er auf jedem Dach der Stadt einen Drachen ...'::text,'steigen lassen wird'::text,'steigen lässt'::text,'steigen lassen wird'::text,'Süße, er hat mir erzählt, dass er auf jedem Dach der Stadt einen Drachen steigen lassen wird.'::text),
(302479,33609,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що ... повітряного змія на кожному даху в місті.'::text,'збирається запускати'::text,'запускає'::text,'збирається запускати'::text,'Подруго, він сказав мені, що збирається запускати повітряного змія на кожному даху в місті.'::text),
(302478,33609,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que ... una cometa en cada azotea de la ciudad.'::text,'va a volar'::text,'vuela'::text,'va a volar'::text,'Tía, me dijo que va a volar una cometa en cada azotea de la ciudad.'::text),
(302477,33609,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''il ... un cerf-volant sur chaque toit de la ville.'::text,'va faire voler'::text,'fait voler'::text,'va faire voler'::text,'Meuf, il m''a dit qu''il va faire voler un cerf-volant sur chaque toit de la ville.'::text),
(302480,33609,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana dedi ki şehirdeki her çatıda uçurtma ...'::text,'uçuracak'::text,'uçurur'::text,'uçuracak'::text,'Kızım, bana dedi ki şehirdeki her çatıda uçurtma uçuracak.'::text),
(302481,33609,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta nekem, hogy a város minden háztetején sárkányt ...'::text,'fog eregetni'::text,'ereget'::text,'fog eregetni'::text,'Csajszi, azt mondta nekem, hogy a város minden háztetején sárkányt fog eregetni.'::text),
(302484,33610,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hey, angeblich reißt die Schnur, also ... sein Drachen wegfliegen.'::text,'wird'::text,'wird'::text,NULL::text,'Hey, angeblich reißt die Schnur, also wird sein Drachen wegfliegen.'::text),
(302488,33610,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гей, кажуть, нитка рветься, тож його змій ...'::text,'збирається відлетіти'::text,'відлетить'::text,NULL::text,'Гей, кажуть, нитка рветься, тож його змій збирається відлетіти.'::text),
(302487,33610,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer la cuerda se está rompiendo, así que su cometa ...'::text,'va a salir volando'::text,'saldrá volando'::text,NULL::text,'Oye, al parecer la cuerda se está rompiendo, así que su cometa va a salir volando.'::text),
(302486,33610,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hé, apparemment la ficelle est en train de casser, donc son cerf-volant ...'::text,'va s''envoler'::text,'s''envolera'::text,NULL::text,'Hé, apparemment la ficelle est en train de casser, donc son cerf-volant va s''envoler.'::text),
(302489,33610,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hey, duyduğuma göre ip kopuyor, yani uçurtması ...'::text,'uçup gidecek'::text,'uçup gidecek'::text,NULL::text,'Hey, duyduğuma göre ip kopuyor, yani uçurtması uçup gidecek.'::text),
(302490,33610,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hé, állítólag szakad a zsinór, szóval el ... repülni a sárkánya.'::text,'fog'::text,'fog'::text,NULL::text,'Hé, állítólag szakad a zsinór, szóval el fog repülni a sárkánya.'::text),
(302493,33611,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, du brauchst voll viel ..., um so einen Drachen steigen zu lassen, echt jetzt.'::text,'Wind'::text,'Wind'::text,'einen Wind'::text,'Bro, du brauchst voll viel Wind, um so einen Drachen steigen zu lassen, echt jetzt.'::text),
(302497,33611,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, тобі треба дуже багато ..., щоб отак запускати змія, реально.'::text,'вітру'::text,'вітрів'::text,'вітру'::text,'Бро, тобі треба дуже багато вітру, щоб отак запускати змія, реально.'::text),
(302496,33611,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, necesitas un montón de ... para volar una cometa así, en serio.'::text,'viento'::text,'viento'::text,'un viento'::text,'Tío, necesitas un montón de viento para volar una cometa así, en serio.'::text),
(302495,33611,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il te faut plein de ... pour faire voler un cerf-volant comme ça, sérieux.'::text,'vent'::text,'vent'::text,'un vent'::text,'Frère, il te faut plein de vent pour faire voler un cerf-volant comme ça, sérieux.'::text),
(302498,33611,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, böyle uçurtma uçurmak için baya çok ... lazım, cidden.'::text,'rüzgâr'::text,'rüzgârlar'::text,'bir rüzgâr'::text,'Kanka, böyle uçurtma uçurmak için baya çok rüzgâr lazım, cidden.'::text),
(302499,33611,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, rengeteg ... kell, hogy így eregess egy sárkányt, komolyan.'::text,'szél'::text,'szél'::text,'egy szél'::text,'Tesó, rengeteg szél kell, hogy így eregess egy sárkányt, komolyan.'::text),
(302502,33612,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wie ... Drachen sind an dem Himmel? Lowkey Hunderte.'::text,'viele'::text,'viel'::text,'einige'::text,'Yo, wie viele Drachen sind an dem Himmel? Lowkey Hunderte.'::text),
(302506,33612,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, ... повітряних зміїв у тому небі? Мабуть, сотні.'::text,'скільки'::text,'скільки'::text,'кілька'::text,'Йо, скільки повітряних зміїв у тому небі? Мабуть, сотні.'::text),
(302505,33612,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿... cometas hay en ese cielo? Fácil cientos.'::text,'Cuántas'::text,'Cuánto'::text,'Algunas'::text,'Tío, ¿Cuántas cometas hay en ese cielo? Fácil cientos.'::text),
(302504,33612,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... cerfs-volants il y a dans ce ciel ? Genre des centaines.'::text,'combien de'::text,'combien de'::text,'quelques'::text,'Yo, combien de cerfs-volants il y a dans ce ciel ? Genre des centaines.'::text),
(302507,33612,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o gökyüzünde ... uçurtma var? Resmen yüzlerce.'::text,'kaç'::text,'kaç'::text,'birkaç'::text,'Kanka, o gökyüzünde kaç uçurtma var? Resmen yüzlerce.'::text),
(302508,33612,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ... sárkány van azon az égen? Simán több száz.'::text,'hány'::text,'mennyi'::text,'néhány'::text,'Figyu, hány sárkány van azon az égen? Simán több száz.'::text),
(302511,33613,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Himmel ... viele bunte Drachen.'::text,'sind'::text,'ist'::text,'sein'::text,'Am Himmel sind viele bunte Drachen.'::text),
(302515,33613,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У небі ... багато кольорових повітряних зміїв.'::text,'є'::text,'є'::text,'бути'::text,'У небі є багато кольорових повітряних зміїв.'::text),
(302514,33613,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un montón de cometas de colores en el cielo.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay un montón de cometas de colores en el cielo.'::text),
(302513,33613,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... plein de cerfs-volants colorés dans le ciel.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a plein de cerfs-volants colorés dans le ciel.'::text),
(302516,33613,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gökyüzünde bir sürü renkli uçurtma ...'::text,'var'::text,'var'::text,'olmak'::text,'Gökyüzünde bir sürü renkli uçurtma var.'::text),
(302517,33613,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az égen rengeteg színes sárkány ...'::text,'van'::text,'van'::text,'lenni'::text,'Az égen rengeteg színes sárkány van.'::text),
(302520,33614,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Dach hat eine Regel: Jeder ... seinen Drachen mit beiden Händen halten.'::text,'muss'::text,'muss'::text,'sollte'::text,'Das Dach hat eine Regel: Jeder muss seinen Drachen mit beiden Händen halten.'::text),
(302524,33614,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На даху є правило: кожен ... тримати свого змія обома руками.'::text,'має'::text,'мусить'::text,'мав би'::text,'На даху є правило: кожен має тримати свого змія обома руками.'::text),
(302523,33614,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La azotea tiene una norma: todo el mundo ... sujetar su cometa con las dos manos.'::text,'tiene que'::text,'debe'::text,'debería'::text,'La azotea tiene una norma: todo el mundo tiene que sujetar su cometa con las dos manos.'::text),
(302522,33614,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le toit a une règle : tout le monde ... tenir son cerf-volant à deux mains.'::text,'doit'::text,'doit'::text,'devrait'::text,'Le toit a une règle : tout le monde doit tenir son cerf-volant à deux mains.'::text),
(302525,33614,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çatının bir kuralı var: herkes uçurtmasını iki eliyle ...'::text,'tutmak zorunda'::text,'tutmalı'::text,'tutmalı'::text,'Çatının bir kuralı var: herkes uçurtmasını iki eliyle tutmak zorunda.'::text),
(302526,33614,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tetőn szabály van: mindenkinek két kézzel ... tartania a sárkányát.'::text,'kell'::text,'kell'::text,'kellene'::text,'A tetőn szabály van: mindenkinek két kézzel kell tartania a sárkányát.'::text),
(308091,34233,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Eltern ... null Freizeit! Das ist eine Katastrophe!'::text,'haben'::text,'hat'::text,'haben'::text,'Die Eltern haben null Freizeit! Das ist eine Katastrophe!'::text),
(308095,34233,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Батьки ... нуль вільного часу! Це катастрофа!'::text,'мають'::text,'має'::text,'мають'::text,'Батьки мають нуль вільного часу! Це катастрофа!'::text),
(308094,34233,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los padres ... cero tiempo libre! ¡Es un desastre!'::text,'tienen'::text,'tiene'::text,'tienen'::text,'¡Los padres tienen cero tiempo libre! ¡Es un desastre!'::text),
