(308100,34234,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Eltern ... die Kinder jeden Abend ins Bett.'::text,'bringen'::text,'bringt'::text,'bringend'::text,'Die Eltern bringen die Kinder jeden Abend ins Bett.'::text),
(308104,34234,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Батьки ... дітей спати щовечора.'::text,'вкладають'::text,'вкладає'::text,'вкладаючи'::text,'Батьки вкладають дітей спати щовечора.'::text),
