(308105,34234,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebeveynler çocukları her gece yatağa ...'::text,'götürürler'::text,'götürür'::text,'götürerek'::text,'Ebeveynler çocukları her gece yatağa götürürler.'::text),
