(308109,34235,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beide ... helfen den Kleinkindern mit den Bauklötzen.'::text,'Eltern'::text,'Elternteil'::text,'Eltern'::text,'Beide Eltern helfen den Kleinkindern mit den Bauklötzen.'::text),
(308113,34235,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обидва ... допомагають малюкам із кубиками.'::text,'батьки'::text,'батько'::text,'батьки'::text,'Обидва батьки допомагають малюкам із кубиками.'::text),
(308112,34235,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los dos ... ayudan a los pequeños con los bloques.'::text,'padres'::text,'padre'::text,'padres'::text,'Los dos padres ayudan a los pequeños con los bloques.'::text),
(308111,34235,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux ... aident les tout-petits avec les cubes.'::text,'parents'::text,'parent'::text,'parents'::text,'Les deux parents aident les tout-petits avec les cubes.'::text),
