(308136,34238,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mutter füttert ... Baby, weil ein Elternteil das Baby füttert.'::text,'ihr'::text,'sein'::text,'sein'::text,'Die Mutter füttert ihr Baby, weil ein Elternteil das Baby füttert.'::text),
(308140,34238,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мама годує ... малюка, бо батько чи мати годує малюка.'::text,'свого'::text,'свого'::text,'свого'::text,'Мама годує свого малюка, бо батько чи мати годує малюка.'::text),
(308139,34238,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La madre alimenta a ... bebé, porque un progenitor alimenta al bebé.'::text,'su'::text,'su'::text,'su'::text,'La madre alimenta a su bebé, porque un progenitor alimenta al bebé.'::text),
