(308145,34239,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Turm wird einstürzen! Ein Elternteil ... ihn halten!'::text,'sollte'::text,'soll'::text,'sollte'::text,'Der Turm wird einstürzen! Ein Elternteil sollte ihn halten!'::text),
(308149,34239,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вежа зараз впаде! Хтось із батьків ... її тримати!'::text,'мав би'::text,'буде'::text,'мав би'::text,'Вежа зараз впаде! Хтось із батьків мав би її тримати!'::text),
(308148,34239,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La torre se va a caer! ¡Uno de los padres ... sujetarla!'::text,'debería'::text,'deberá'::text,'debería'::text,'¡La torre se va a caer! ¡Uno de los padres debería sujetarla!'::text),
(308147,34239,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tour va s''écrouler ! Un parent ... la tenir !'::text,'devrait'::text,'devra'::text,'devrait'::text,'La tour va s''écrouler ! Un parent devrait la tenir !'::text),
