(308151,34239,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A torony össze fog dőlni! Egy szülőnek ... tartania!'::text,'kellene'::text,'kell'::text,'kellene'::text,'A torony össze fog dőlni! Egy szülőnek kellene tartania!'::text),
(324399,36045,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hilfe! An diesem Gleis stehen ...! Welcher ist meiner?'::text,'2 Züge'::text,'2 Zug'::text,'2 Züge'::text,'Hilfe! An diesem Gleis stehen 2 Züge! Welcher ist meiner?'::text),
