(324404,36045,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İmdat! Bu peronda ... var! Hangisi benim?'::text,'2 tren'::text,'2 tren'::text,'2 trenler'::text,'İmdat! Bu peronda 2 tren var! Hangisi benim?'::text),
