(308824,34314,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Приходить більше людей, тож скоро ... більше людей.'::text,'буде'::text,'було'::text,'бути'::text,'Приходить більше людей, тож скоро буде більше людей.'::text),
(308823,34314,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Viene más gente, así que pronto ... más gente.'::text,'habrá'::text,'hubo'::text,'haber'::text,'Viene más gente, así que pronto habrá más gente.'::text),
(308822,34314,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plus de gens arrivent, donc bientôt ... plus de gens.'::text,'il y aura'::text,'il y avait'::text,'il y a'::text,'Plus de gens arrivent, donc bientôt il y aura plus de gens.'::text),
(308825,34314,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha çok insan geliyor, yani yakında daha çok insan ...'::text,'olacak'::text,'vardı'::text,'olmak'::text,'Daha çok insan geliyor, yani yakında daha çok insan olacak.'::text),
(308826,34314,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyre több ember jön, szóval hamarosan még több ember ...'::text,'lesz'::text,'volt'::text,'lenni'::text,'Egyre több ember jön, szóval hamarosan még több ember lesz.'::text),
(305625,33959,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen früh ... die Person 5 Kilometer gehen, um das Ziel zu erreichen.'::text,'wird'::text,'geht'::text,'wird'::text,'Morgen früh wird die Person 5 Kilometer gehen, um das Ziel zu erreichen.'::text),
(305629,33959,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра вранці ця людина ... 5 кілометрів, щоб досягти цілі.'::text,'збирається пройти'::text,'проходить'::text,'пройде'::text,'Завтра вранці ця людина збирається пройти 5 кілометрів, щоб досягти цілі.'::text),
(305628,33959,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana por la mañana la persona ... 5 kilómetros para alcanzar el objetivo.'::text,'va a caminar'::text,'camina'::text,'caminará'::text,'Mañana por la mañana la persona va a caminar 5 kilómetros para alcanzar el objetivo.'::text),
(305627,33959,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain matin, la personne ... 5 kilomètres pour atteindre l''objectif.'::text,'va marcher'::text,'marche'::text,'marchera'::text,'Demain matin, la personne va marcher 5 kilomètres pour atteindre l''objectif.'::text),
(305630,33959,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın sabah kişi hedefe ulaşmak için 5 kilometre ...'::text,'yürüyecek'::text,'yürür'::text,'yürüyecek'::text,'Yarın sabah kişi hedefe ulaşmak için 5 kilometre yürüyecek.'::text),
(305631,33959,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap reggel a személy 5 kilométert ..., hogy elérje a célt.'::text,'fog gyalogolni'::text,'gyalogol'::text,'fog gyalogolni'::text,'Holnap reggel a személy 5 kilométert fog gyalogolni, hogy elérje a célt.'::text),
(305634,33960,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemand ist hier, also ... das ein ruhiger Morgen sein, weil niemand hier ist.'::text,'wird'::text,'wird'::text,NULL::text,'Niemand ist hier, also wird das ein ruhiger Morgen sein, weil niemand hier ist.'::text),
(305638,33960,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тут нікого немає, тож це ... тихий ранок, бо тут нікого немає.'::text,'буде'::text,'буде'::text,NULL::text,'Тут нікого немає, тож це буде тихий ранок, бо тут нікого немає.'::text),
(305637,33960,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No hay nadie, así que esta ... una mañana tranquila, porque no hay nadie.'::text,'va a ser'::text,'será'::text,NULL::text,'No hay nadie, así que esta va a ser una mañana tranquila, porque no hay nadie.'::text),
(305636,33960,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''y a personne, donc ce ... une matinée calme, parce qu''il n''y a personne.'::text,'va être'::text,'sera'::text,NULL::text,'Il n''y a personne, donc ce va être une matinée calme, parce qu''il n''y a personne.'::text),
(305639,33960,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burada kimse yok, yani bu sakin bir sabah ..., çünkü burada kimse yok.'::text,'olacak'::text,'olacak'::text,NULL::text,'Burada kimse yok, yani bu sakin bir sabah olacak, çünkü burada kimse yok.'::text),
(305640,33960,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senki sincs itt, szóval ez nyugodt reggel ..., mert senki sincs itt.'::text,'lesz'::text,'lesz'::text,NULL::text,'Senki sincs itt, szóval ez nyugodt reggel lesz, mert senki sincs itt.'::text),
(305643,33961,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du bringst so viel ... in diesen leeren Morgen.'::text,'Energie'::text,'Energie'::text,'eine Energie'::text,'Ehrlich, du bringst so viel Energie in diesen leeren Morgen.'::text),
(305647,33961,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти приносиш стільки ... в цей порожній ранок.'::text,'енергії'::text,'енергії'::text,'енергії'::text,'Чесно, ти приносиш стільки енергії в цей порожній ранок.'::text),
(305646,33961,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, traes tanta ... a esta mañana vacía.'::text,'energía'::text,'energía'::text,'una energía'::text,'La verdad, traes tanta energía a esta mañana vacía.'::text),
(305645,33961,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu apportes tellement ... à cette matinée vide.'::text,'d''énergie'::text,'d''énergie'::text,'d''une énergie'::text,'Franchement, tu apportes tellement d''énergie à cette matinée vide.'::text),
(305648,33961,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası bu boş sabaha çok fazla ... getiriyorsun.'::text,'enerji'::text,'enerjiler'::text,'bir enerji'::text,'Açıkçası bu boş sabaha çok fazla enerji getiriyorsun.'::text),
(305649,33961,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, annyi ... hozol ebbe az üres reggelbe.'::text,'energiát'::text,'energiát'::text,'egy energiát'::text,'Őszintén, annyi energiát hozol ebbe az üres reggelbe.'::text),
(305661,33963,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Morgen ... keine Autos auf der Straße.'::text,'sind'::text,'ist'::text,'sein'::text,'Heute Morgen sind keine Autos auf der Straße.'::text),
(305665,33963,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вранці на дорозі ... машин.'::text,'немає'::text,'немає'::text,'не бути'::text,'Сьогодні вранці на дорозі немає машин.'::text),
(305664,33963,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta mañana ... coches en la carretera.'::text,'no hay'::text,'no hay'::text,'no hay'::text,'Esta mañana no hay coches en la carretera.'::text),
(305663,33963,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce matin, ... de voitures sur la route.'::text,'il n''y a pas'::text,'il n''y a pas'::text,'il n''y a pas'::text,'Ce matin, il n''y a pas de voitures sur la route.'::text),
(305666,33963,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabah yolda hiç araba ...'::text,'yok'::text,'yok'::text,'olmamak'::text,'Bu sabah yolda hiç araba yok.'::text),
(305667,33963,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma reggel ... autók az úton.'::text,'nincsenek'::text,'nincs'::text,'nem lenni'::text,'Ma reggel nincsenek autók az úton.'::text),
(305670,33964,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Zug fährt um sechs, also ... diese Person jeden Morgen früh aufstehen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Der Zug fährt um sechs, also muss diese Person jeden Morgen früh aufstehen.'::text),
(305674,33964,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Потяг відходить о шостій, тож ця людина ... вставати рано щоранку.'::text,'має'::text,'мусить'::text,'мала б'::text,'Потяг відходить о шостій, тож ця людина має вставати рано щоранку.'::text),
(305673,33964,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tren sale a las seis, así que esta persona ... levantarse temprano cada mañana.'::text,'tiene que'::text,'debe'::text,'debería'::text,'El tren sale a las seis, así que esta persona tiene que levantarse temprano cada mañana.'::text),
(305672,33964,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le train part à six heures, donc cette personne ... se lever tôt tous les matins.'::text,'doit'::text,'doit'::text,'devrait'::text,'Le train part à six heures, donc cette personne doit se lever tôt tous les matins.'::text),
(305675,33964,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tren altıda kalkıyor, bu yüzden bu kişi her sabah erken ...'::text,'kalkmak zorunda'::text,'kalkmalı'::text,'kalkmalı'::text,'Tren altıda kalkıyor, bu yüzden bu kişi her sabah erken kalkmak zorunda.'::text),
(305676,33964,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vonat hatkor indul, ezért ennek a személynek minden reggel korán ... kelnie.'::text,'kell'::text,'kell'::text,'kellene'::text,'A vonat hatkor indul, ezért ennek a személynek minden reggel korán kell kelnie.'::text),
(305679,33965,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, du ... jeden Morgen so früh rauskommen, ohne Witz.'::text,'solltest'::text,'sollst'::text,'solltest'::text,'Alter, du solltest jeden Morgen so früh rauskommen, ohne Witz.'::text),
(305683,33965,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, ти ... виходити так рано щоранку, без жартів.'::text,'мав би'::text,'будеш'::text,'мав би'::text,'Чувак, ти мав би виходити так рано щоранку, без жартів.'::text),
(305682,33965,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... salir así de temprano cada mañana, en serio.'::text,'deberías'::text,'deberás'::text,'deberías'::text,'Tío, deberías salir así de temprano cada mañana, en serio.'::text),
(305681,33965,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, tu ... sortir aussi tôt tous les matins, sans mentir.'::text,'devrais'::text,'devras'::text,'devrais'::text,'Mec, tu devrais sortir aussi tôt tous les matins, sans mentir.'::text),
(305684,33965,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, her sabah bu kadar erken ..., cidden.'::text,'çıkmalısın'::text,'çıkacaksın'::text,'çıkmalısın'::text,'Kanka, her sabah bu kadar erken çıkmalısın, cidden.'::text),
(305685,33965,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, minden reggel ilyen korán ... kijönnöd, komolyan.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Tesó, minden reggel ilyen korán kellene kijönnöd, komolyan.'::text),
(305688,33966,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, die Stadt ist heute Morgen leer, ... noch keiner wach ist, echt krass.'::text,'weil'::text,'also'::text,'aber'::text,'Yo, die Stadt ist heute Morgen leer, weil noch keiner wach ist, echt krass.'::text),
(305692,33966,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, місто сьогодні вранці порожнє, ... ще ніхто не встав, якось дико.'::text,'бо'::text,'тому'::text,'але'::text,'Йо, місто сьогодні вранці порожнє, бо ще ніхто не встав, якось дико.'::text),
(305691,33966,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la ciudad está vacía esta mañana ... nadie se ha levantado aún, qué locura.'::text,'porque'::text,'así que'::text,'pero'::text,'Tío, la ciudad está vacía esta mañana porque nadie se ha levantado aún, qué locura.'::text),
(305690,33966,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, la ville est vide ce matin ... personne n''est encore levé, trop fou.'::text,'parce que'::text,'donc'::text,'mais'::text,'Yo, la ville est vide ce matin parce que personne n''est encore levé, trop fou.'::text),
(305693,33966,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, şehir bu sabah bomboş ... henüz kimse kalkmadı, bayağı çılgın.'::text,'çünkü'::text,'bu yüzden'::text,'ama'::text,'Kanka, şehir bu sabah bomboş çünkü henüz kimse kalkmadı, bayağı çılgın.'::text),
(305694,33966,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a város üres ma reggel, ... még senki sincs fent, elég durva.'::text,'mert'::text,'ezért'::text,'de'::text,'Figyu, a város üres ma reggel, mert még senki sincs fent, elég durva.'::text),
(309081,34343,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Apotheke ... eine Million Schubladen! Ich bin buchstäblich geschockt!'::text,'hat'::text,'haben'::text,'hat'::text,'Diese Apotheke hat eine Million Schubladen! Ich bin buchstäblich geschockt!'::text),
(309085,34343,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця аптека ... мільйон шухляд! Я буквально в шоці!'::text,'має'::text,'мати'::text,'має'::text,'Ця аптека має мільйон шухляд! Я буквально в шоці!'::text),
(309084,34343,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esta farmacia ... un millón de cajones! ¡Estoy literalmente en shock!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡Esta farmacia tiene un millón de cajones! ¡Estoy literalmente en shock!'::text),
(309083,34343,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette pharmacie ... un million de tiroirs ! Je suis littéralement sous le choc !'::text,'a'::text,'ont'::text,'a'::text,'Cette pharmacie a un million de tiroirs ! Je suis littéralement sous le choc !'::text),
(309086,34343,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu eczanenin bir milyon çekmecesi ...! Resmen şoktayım!'::text,'var'::text,'var'::text,'var'::text,'Bu eczanenin bir milyon çekmecesi var! Resmen şoktayım!'::text),
(309087,34343,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ennek a gyógyszertárnak egymillió fiókja ...! Szó szerint sokkban vagyok!'::text,'van'::text,'van'::text,'van'::text,'Ennek a gyógyszertárnak egymillió fiókja van! Szó szerint sokkban vagyok!'::text),
(309090,34344,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In dieser Apotheke ... sie jeden Tag auf eine riesige Leiter! Absolut beängstigend!'::text,'klettert'::text,'klettern'::text,'kletternd'::text,'In dieser Apotheke klettert sie jeden Tag auf eine riesige Leiter! Absolut beängstigend!'::text),
(309094,34344,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У цій аптеці вона щодня ... на величезну драбину! Просто жах!'::text,'лізе'::text,'лізти'::text,'лізучи'::text,'У цій аптеці вона щодня лізе на величезну драбину! Просто жах!'::text),
(309093,34344,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡En esta farmacia ella ... una escalera enorme cada día! ¡Absolutamente aterrador!'::text,'sube'::text,'subir'::text,'subiendo'::text,'¡En esta farmacia ella sube una escalera enorme cada día! ¡Absolutamente aterrador!'::text),
(309092,34344,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans cette pharmacie, elle ... sur une échelle immense tous les jours ! Absolument terrifiant !'::text,'grimpe'::text,'grimper'::text,'grimpant'::text,'Dans cette pharmacie, elle grimpe sur une échelle immense tous les jours ! Absolument terrifiant !'::text),
(309095,34344,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu eczanede her gün kocaman bir merdivene ...! Kesinlikle korkunç!'::text,'tırmanır'::text,'tırmanmak'::text,'tırmanarak'::text,'Bu eczanede her gün kocaman bir merdivene tırmanır! Kesinlikle korkunç!'::text),
(309096,34344,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a gyógyszertárban minden nap ... egy óriási létrára! Abszolút ijesztő!'::text,'felmászik'::text,'felmászni'::text,'felmászó'::text,'Ebben a gyógyszertárban minden nap felmászik egy óriási létrára! Abszolút ijesztő!'::text),
(309099,34345,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mir die Apotheke helfen? Meine Nase ist eine Katastrophe!'::text,'Kann'::text,NULL::text,'Ist'::text,'Kann mir die Apotheke helfen? Meine Nase ist eine Katastrophe!'::text),
(309103,34345,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чи ... мені допомогти аптека? Мій ніс — катастрофа!'::text,'може'::text,NULL::text,'є'::text,'Чи може мені допомогти аптека? Мій ніс — катастрофа!'::text),
(309102,34345,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... ayudarme la farmacia? ¡Mi nariz es un desastre!'::text,'Puede'::text,NULL::text,'Está'::text,'¿Puede ayudarme la farmacia? ¡Mi nariz es un desastre!'::text),
(309101,34345,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Est-ce que la pharmacie ... m''aider ? Mon nez est une catastrophe !'::text,'peut'::text,NULL::text,'est'::text,'Est-ce que la pharmacie peut m''aider ? Mon nez est une catastrophe !'::text),
(309104,34345,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eczane bana ... mi? Burnum felaket!'::text,'yardım edebilir'::text,NULL::text,NULL::text,'Eczane bana yardım edebilir mi? Burnum felaket!'::text),
(309105,34345,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... nekem segíteni a gyógyszertár? Az orrom egy katasztrófa!'::text,'Tud'::text,NULL::text,'Van'::text,'Tud nekem segíteni a gyógyszertár? Az orrom egy katasztrófa!'::text),
(309108,34346,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der alte Laden mit den Holzschubladen ist auch ... Apotheke.'::text,'eine'::text,'die'::text,'eine'::text,'Der alte Laden mit den Holzschubladen ist auch eine Apotheke.'::text),
(309112,34346,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стара крамниця з дерев''яними шухлядами — теж ... аптека.'::text,''::text,NULL::text,NULL::text,'Стара крамниця з дерев''яними шухлядами — теж аптека.'::text),
(309111,34346,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La vieja tienda con cajones de madera también es ... farmacia.'::text,'una'::text,'la'::text,'una'::text,'La vieja tienda con cajones de madera también es una farmacia.'::text),
(309110,34346,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La vieille boutique aux tiroirs en bois est aussi ... pharmacie.'::text,'une'::text,'la'::text,'une'::text,'La vieille boutique aux tiroirs en bois est aussi une pharmacie.'::text),
(309113,34346,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahşap çekmeceli eski dükkân da ... eczane.'::text,'bir'::text,NULL::text,'bir'::text,'Ahşap çekmeceli eski dükkân da bir eczane.'::text),
(309114,34346,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A régi, fafiókos bolt is ... gyógyszertár.'::text,'egy'::text,'a'::text,'egy'::text,'A régi, fafiókos bolt is egy gyógyszertár.'::text),
(309117,34347,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Apotheke hat Hunderte Holzschubladen.'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Diese Apotheke hat Hunderte Holzschubladen.'::text),
(309121,34347,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... аптека має сотні дерев''яних шухляд.'::text,'Ця'::text,'Ці'::text,'Ті'::text,'Ця аптека має сотні дерев''яних шухляд.'::text),
(309120,34347,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... farmacia tiene cientos de cajones de madera.'::text,'Esta'::text,'Estas'::text,'Esas'::text,'Esta farmacia tiene cientos de cajones de madera.'::text),
(309119,34347,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pharmacie a des centaines de tiroirs en bois.'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette pharmacie a des centaines de tiroirs en bois.'::text),
(309122,34347,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... eczanenin yüzlerce ahşap çekmecesi var.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu eczanenin yüzlerce ahşap çekmecesi var.'::text),
(309123,34347,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... gyógyszertárnak több száz fafiókja van.'::text,'Ennek a'::text,'Ezeknek a'::text,'Azoknak a'::text,'Ennek a gyógyszertárnak több száz fafiókja van.'::text),
(309126,34348,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... Nase ist so rot, er muss echt zur Apotheke.'::text,'seine'::text,'ihre'::text,'seine'::text,'Bro, seine Nase ist so rot, er muss echt zur Apotheke.'::text),
(309130,34348,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... ніс такий червоний, йому треба в аптеку.'::text,'його'::text,'її'::text,'його'::text,'Бро, його ніс такий червоний, йому треба в аптеку.'::text),
(309129,34348,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... nariz está tan roja que tiene que ir a la farmacia.'::text,'su'::text,'su'::text,'su'::text,'Tío, su nariz está tan roja que tiene que ir a la farmacia.'::text),
(309128,34348,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ... nez est trop rouge, il doit aller à la pharmacie.'::text,'son'::text,'son'::text,'son'::text,'Frère, son nez est trop rouge, il doit aller à la pharmacie.'::text),
(309131,34348,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... burnu çok kırmızı, eczaneye gitmesi lazım.'::text,'onun'::text,'onun'::text,'onun'::text,'Kanka, onun burnu çok kırmızı, eczaneye gitmesi lazım.'::text),
(309132,34348,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, annyira piros ..., hogy el kell mennie a gyógyszertárba.'::text,'az orra'::text,'az orra'::text,'az orra'::text,'Tesó, annyira piros az orra, hogy el kell mennie a gyógyszertárba.'::text),
(309135,34349,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... schließt die Apotheke? Um 22 Uhr, die Deadline.'::text,'Wann'::text,'Wo'::text,'Wer'::text,'Wann schließt die Apotheke? Um 22 Uhr, die Deadline.'::text),
(309139,34349,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... зачиняється аптека? О 22:00, дедлайн.'::text,'Коли'::text,'Де'::text,'Хто'::text,'Коли зачиняється аптека? О 22:00, дедлайн.'::text),
(309138,34349,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... cierra la farmacia? A las 22:00, la fecha límite.'::text,'Cuándo'::text,'Dónde'::text,'Quién'::text,'¿Cuándo cierra la farmacia? A las 22:00, la fecha límite.'::text),
