(309140,34349,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eczane ... kapanıyor? Saat 22.00''de, son saat.'::text,'ne zaman'::text,'nerede'::text,'kim'::text,'Eczane ne zaman kapanıyor? Saat 22.00''de, son saat.'::text),
(309141,34349,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... zár be a gyógyszertár? Este 10-kor, ez a határidő.'::text,'Mikor'::text,'Hol'::text,'Ki'::text,'Mikor zár be a gyógyszertár? Este 10-kor, ez a határidő.'::text),
(295194,32800,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den silbernen Rahmen an einen Haken.'::text,'hängte'::text,'hängte'::text,'hängt'::text,'Er hängte den silbernen Rahmen an einen Haken.'::text),
(295198,32800,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... срібну рамку на гачок.'::text,'повісив'::text,'повісив'::text,'вішає'::text,'Він повісив срібну рамку на гачок.'::text),
(295197,32800,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... el marco plateado en un gancho.'::text,'colgó'::text,'colgó'::text,'cuelga'::text,'Él colgó el marco plateado en un gancho.'::text),
(295196,32800,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le cadre argenté à un crochet.'::text,'a accroché'::text,'a accroché'::text,'accroche'::text,'Il a accroché le cadre argenté à un crochet.'::text),
(295199,32800,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gümüş çerçeveyi bir kancaya ...'::text,'astı'::text,'astı'::text,'asar'::text,'Gümüş çerçeveyi bir kancaya astı.'::text),
(295200,32800,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... az ezüst keretet egy kampóra.'::text,'Felakasztotta'::text,'Felakasztotta'::text,'Felakasztja'::text,'Felakasztotta az ezüst keretet egy kampóra.'::text),
(295212,32802,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Rahmen, weil der Rahmen in seinen Händen ist.'::text,'hält'::text,'hält'::text,'hält'::text,'Er hält den Rahmen, weil der Rahmen in seinen Händen ist.'::text),
(295216,32802,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... рамку, бо рамка в його руках.'::text,'тримає'::text,'тримає'::text,'тримає'::text,'Він тримає рамку, бо рамка в його руках.'::text),
(295215,32802,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... el marco, porque el marco está en sus manos.'::text,'está sujetando'::text,'sujeta'::text,'está sujetando'::text,'Él está sujetando el marco, porque el marco está en sus manos.'::text),
(295214,32802,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le cadre, parce que le cadre est dans ses mains.'::text,'tient'::text,'tient'::text,'tient'::text,'Il tient le cadre, parce que le cadre est dans ses mains.'::text),
(295217,32802,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çerçeveyi ..., çünkü çerçeve onun elinde.'::text,'tutuyor'::text,'tutar'::text,'tutuyor'::text,'Çerçeveyi tutuyor, çünkü çerçeve onun elinde.'::text),
(295218,32802,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a keretet, mert a keret a kezében van.'::text,'Fogja'::text,'Fogja'::text,'Fogja'::text,'Fogja a keretet, mert a keret a kezében van.'::text),
(295221,32803,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Normalerweise malst du, aber heute ... du einen Rahmen auf.'::text,'hängst'::text,'hängst'::text,NULL::text,'Respekt: Normalerweise malst du, aber heute hängst du einen Rahmen auf.'::text),
(295225,32803,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: зазвичай ти малюєш, але сьогодні ... рамку.'::text,'вішаєш'::text,'вішаєш'::text,NULL::text,'Респект: зазвичай ти малюєш, але сьогодні вішаєш рамку.'::text),
(295224,32803,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: normalmente pintas, pero hoy ... un marco.'::text,'estás colgando'::text,'cuelgas'::text,NULL::text,'Respeto: normalmente pintas, pero hoy estás colgando un marco.'::text),
(295223,32803,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : d''habitude tu peins, mais aujourd''hui tu ... un cadre.'::text,'es en train d''accrocher'::text,'accroches'::text,NULL::text,'Respect : d''habitude tu peins, mais aujourd''hui tu es en train d''accrocher un cadre.'::text),
(295226,32803,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal: genelde resim yaparsın ama bugün bir çerçeve ...'::text,'asıyorsun'::text,'asarsın'::text,NULL::text,'Helal: genelde resim yaparsın ama bugün bir çerçeve asıyorsun.'::text),
(295227,32803,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: általában festesz, de ma egy keretet ... fel.'::text,'akasztasz'::text,'akasztasz'::text,NULL::text,'Respekt: általában festesz, de ma egy keretet akasztasz fel.'::text),
(295230,32804,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, aber deine Wand ist ikonisch. Ich glaube, dass du bald noch einen Rahmen ...'::text,'kaufen wirst'::text,'kaufst'::text,'kauftest'::text,'Okay, aber deine Wand ist ikonisch. Ich glaube, dass du bald noch einen Rahmen kaufen wirst.'::text),
(295234,32804,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, але твоя стіна — культова. Думаю, ти скоро ... ще одну рамку.'::text,'купиш'::text,'купуєш'::text,'купив'::text,'Окей, але твоя стіна — культова. Думаю, ти скоро купиш ще одну рамку.'::text),
(295233,32804,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pero tu pared es icónica. Creo que pronto ... otro marco.'::text,'comprarás'::text,'compras'::text,'compraste'::text,'Vale, pero tu pared es icónica. Creo que pronto comprarás otro marco.'::text),
(295232,32804,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'OK, mais ton mur est iconique. Je pense que tu ... un autre cadre bientôt.'::text,'achèteras'::text,'achètes'::text,'as acheté'::text,'OK, mais ton mur est iconique. Je pense que tu achèteras un autre cadre bientôt.'::text),
(295235,32804,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam ama duvarın efsane. Bence yakında bir çerçeve daha ...'::text,'alacaksın'::text,'alırsın'::text,'aldın'::text,'Tamam ama duvarın efsane. Bence yakında bir çerçeve daha alacaksın.'::text),
(295236,32804,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, de a falad ikonikus. Szerintem hamarosan ... még egy keretet.'::text,'fogsz venni'::text,'veszel'::text,'vettél'::text,'Oké, de a falad ikonikus. Szerintem hamarosan fogsz venni még egy keretet.'::text),
(295239,32805,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dein Plan ist ziemlich beeindruckend: Du ... den ganzen Flur mit Rahmen füllen.'::text,'wirst'::text,'füllst'::text,'wirst'::text,'Dein Plan ist ziemlich beeindruckend: Du wirst den ganzen Flur mit Rahmen füllen.'::text),
(295243,32805,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твій план доволі вражає: ти ... весь коридор рамками.'::text,'збираєшся заповнити'::text,'заповнюєш'::text,'збираєшся заповнити'::text,'Твій план доволі вражає: ти збираєшся заповнити весь коридор рамками.'::text),
(295242,32805,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu plan es bastante impresionante: ... todo el pasillo de marcos.'::text,'vas a llenar'::text,'llenas'::text,'vas a llenar'::text,'Tu plan es bastante impresionante: vas a llenar todo el pasillo de marcos.'::text),
(295241,32805,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ton plan est plutôt impressionnant : tu ... tout le couloir de cadres.'::text,'vas remplir'::text,'remplis'::text,'vas remplir'::text,'Ton plan est plutôt impressionnant : tu vas remplir tout le couloir de cadres.'::text),
(295244,32805,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Planın baya etkileyici: bütün koridoru çerçevelerle ...'::text,'dolduracaksın'::text,'doldurursun'::text,'dolduracaksın'::text,'Planın baya etkileyici: bütün koridoru çerçevelerle dolduracaksın.'::text),
(295245,32805,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elég lenyűgöző a terved: az egész folyosót ... keretekkel.'::text,'meg fogod tölteni'::text,'megtöltöd'::text,'meg fogod tölteni'::text,'Elég lenyűgöző a terved: az egész folyosót meg fogod tölteni keretekkel.'::text),
(295248,32806,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi: Der Rahmen hängt nicht gerade, also ... er ihn nochmal verschieben.'::text,'wird'::text,'wird'::text,NULL::text,'Ein echter Profi: Der Rahmen hängt nicht gerade, also wird er ihn nochmal verschieben.'::text),
(295252,32806,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній профі: рамка висить криво, тож він ... її знову.'::text,'збирається посунути'::text,'посуне'::text,NULL::text,'Справжній профі: рамка висить криво, тож він збирається посунути її знову.'::text),
(295251,32806,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo un profesional: el marco no está recto, así que lo ... otra vez.'::text,'va a mover'::text,'moverá'::text,NULL::text,'Todo un profesional: el marco no está recto, así que lo va a mover otra vez.'::text),
(295250,32806,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai pro : le cadre n''est pas droit, donc il ... encore.'::text,'va le bouger'::text,'le bougera'::text,NULL::text,'Un vrai pro : le cadre n''est pas droit, donc il va le bouger encore.'::text),
(295253,32806,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir profesyonel: çerçeve düz değil, yani onu yine ...'::text,'oynatacak'::text,'oynatacak'::text,NULL::text,'Tam bir profesyonel: çerçeve düz değil, yani onu yine oynatacak.'::text),
(295254,32806,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi: a keret nem egyenes, szóval megint el ... tolni.'::text,'fogja'::text,'fogja'::text,NULL::text,'Igazi profi: a keret nem egyenes, szóval megint el fogja tolni.'::text),
(304455,33829,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... ein riesiges Mittagessen für alle, wird gut.'::text,'hat'::text,'haben'::text,'hat'::text,'Bro, sie hat ein riesiges Mittagessen für alle, wird gut.'::text),
(304459,33829,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... величезний обід для всіх, буде смачно.'::text,'має'::text,'мати'::text,'має'::text,'Бро, вона має величезний обід для всіх, буде смачно.'::text),
(304458,33829,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella ... una comida enorme para todos, va a estar buena.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'Tío, ella tiene una comida enorme para todos, va a estar buena.'::text),
(304457,33829,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle ... un énorme déjeuner pour tout le monde, ça va être bon.'::text,'a'::text,'ont'::text,'a'::text,'Frère, elle a un énorme déjeuner pour tout le monde, ça va être bon.'::text),
(304460,33829,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun herkes için kocaman bir öğle yemeği ..., güzel olacak.'::text,'var'::text,'var'::text,'var'::text,'Kanka, onun herkes için kocaman bir öğle yemeği var, güzel olacak.'::text),
(304461,33829,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, neki ... egy hatalmas ebédje mindenkinek, jó lesz.'::text,'van'::text,'van'::text,'van'::text,'Tesó, neki van egy hatalmas ebédje mindenkinek, jó lesz.'::text),
(304473,33831,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mittagsbudget: 20 Euro für all diese ...'::text,'Pasta'::text,'Pasta'::text,'eine Pasta'::text,'Mittagsbudget: 20 Euro für all diese Pasta.'::text),
(304477,33831,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджет на обід: 20 євро за всю цю ...'::text,'пасту'::text,'пасту'::text,'пасту'::text,'Бюджет на обід: 20 євро за всю цю пасту.'::text),
(304476,33831,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presupuesto de comida: 20 euros por toda esta ...'::text,'pasta'::text,'pasta'::text,'una pasta'::text,'Presupuesto de comida: 20 euros por toda esta pasta.'::text),
(304475,33831,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget déjeuner : 20 euros pour toutes ces ...'::text,'pâtes'::text,'pâtes'::text,'pâtes'::text,'Budget déjeuner : 20 euros pour toutes ces pâtes.'::text),
(304478,33831,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğle yemeği bütçesi: bütün bu ... için 20 euro.'::text,'makarna'::text,'makarnalar'::text,'bir makarna'::text,'Öğle yemeği bütçesi: bütün bu makarna için 20 euro.'::text),
(304479,33831,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebédkeret: 20 euró ezért a sok ...'::text,'tésztáért'::text,'tésztáért'::text,'egy tésztáért'::text,'Ebédkeret: 20 euró ezért a sok tésztáért.'::text),
