(304494,33833,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... diez platos de pasta para comer! ¡Estoy en shock total!'::text,'Hay'::text,'Hay'::text,'Hay'::text,'¡Hay diez platos de pasta para comer! ¡Estoy en shock total!'::text),
(304493,33833,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dix assiettes de pâtes pour le déjeuner ! Je suis complètement sous le choc !'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a dix assiettes de pâtes pour le déjeuner ! Je suis complètement sous le choc !'::text),
(304496,33833,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğle yemeği için on tabak makarna ...! Resmen şoktayım!'::text,'var'::text,'var'::text,'olmak'::text,'Öğle yemeği için on tabak makarna var! Resmen şoktayım!'::text),
(304497,33833,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebédre tíz tányér tészta ...! Teljesen le vagyok döbbenve!'::text,'van'::text,'van'::text,'lenni'::text,'Ebédre tíz tányér tészta van! Teljesen le vagyok döbbenve!'::text),
(304500,33834,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mittagessen ist um eins, also ... sich die Familie jetzt hinsetzen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Mittagessen ist um eins, also muss sich die Familie jetzt hinsetzen.'::text),
(304504,33834,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обід о першій, тож родина ... сісти зараз.'::text,'має'::text,'мусить'::text,'мала б'::text,'Обід о першій, тож родина має сісти зараз.'::text),
(304503,33834,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La comida es a la una, así que la familia ... sentarse ya.'::text,'tiene que'::text,'debe'::text,'debería'::text,'La comida es a la una, así que la familia tiene que sentarse ya.'::text),
(304502,33834,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le déjeuner est à une heure, donc la famille ... s''asseoir maintenant.'::text,'doit'::text,'doit'::text,'devrait'::text,'Le déjeuner est à une heure, donc la famille doit s''asseoir maintenant.'::text),
(304505,33834,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğle yemeği saat birde, bu yüzden aile şimdi ...'::text,'oturmak zorunda'::text,'oturmalı'::text,'oturmalı'::text,'Öğle yemeği saat birde, bu yüzden aile şimdi oturmak zorunda.'::text),
(304506,33834,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ebéd egykor van, ezért a családnak most le ... ülnie.'::text,'kell'::text,'kell'::text,'kellene'::text,'Az ebéd egykor van, ezért a családnak most le kell ülnie.'::text),
(304509,33835,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Mittagessen ist sehr heiß, also ... jeder kurz warten.'::text,'sollte'::text,'soll'::text,'sollte'::text,'Das Mittagessen ist sehr heiß, also sollte jeder kurz warten.'::text),
(304513,33835,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обід дуже гарячий, тож кожен ... хвилинку почекати.'::text,'мав би'::text,'буде'::text,'мав би'::text,'Обід дуже гарячий, тож кожен мав би хвилинку почекати.'::text),
(304512,33835,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La comida está muy caliente, así que todos ... esperar un minuto.'::text,'deberían'::text,'deberán'::text,'deberían'::text,'La comida está muy caliente, así que todos deberían esperar un minuto.'::text),
(304511,33835,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le déjeuner est très chaud, donc tout le monde ... attendre une minute.'::text,'devrait'::text,'devra'::text,'devrait'::text,'Le déjeuner est très chaud, donc tout le monde devrait attendre une minute.'::text),
(304514,33835,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yemek çok sıcak, bu yüzden herkes bir dakika ...'::text,'beklemeli'::text,'bekleyecek'::text,'beklemeli'::text,'Yemek çok sıcak, bu yüzden herkes bir dakika beklemeli.'::text),
(304515,33835,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ebéd nagyon forró, ezért mindenkinek ... várnia egy percet.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Az ebéd nagyon forró, ezért mindenkinek kellene várnia egy percet.'::text),
(304518,33836,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nur ein kleines Mittagessen, eh klar, ... es stehen zwanzig Teller da.'::text,'aber'::text,'also'::text,'weil'::text,'Nur ein kleines Mittagessen, eh klar, aber es stehen zwanzig Teller da.'::text),
(304522,33836,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто невеликий обід, звісно, ... тут двадцять тарілок.'::text,'але'::text,'тому'::text,'бо'::text,'Просто невеликий обід, звісно, але тут двадцять тарілок.'::text),
(304521,33836,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo una comida pequeña, claro, ... hay veinte platos.'::text,'pero'::text,'así que'::text,'porque'::text,'Solo una comida pequeña, claro, pero hay veinte platos.'::text),
(304520,33836,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Juste un petit repas de midi, évidemment, ... il y a vingt assiettes.'::text,'mais'::text,'donc'::text,'parce qu'''::text,'Juste un petit repas de midi, évidemment, mais il y a vingt assiettes.'::text),
(304523,33836,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sadece küçük bir öğle yemeği, belli ki, ... yirmi tabak var.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Sadece küçük bir öğle yemeği, belli ki, ama yirmi tabak var.'::text),
(304524,33836,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak egy kis ebéd, persze, ... húsz tányér van.'::text,'de'::text,'ezért'::text,'mert'::text,'Csak egy kis ebéd, persze, de húsz tányér van.'::text),
(311565,34619,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie ... ihren Regenmantel bei jeder Wanderung, man muss ja trocken bleiben.'::text,'trägt'::text,'tragen'::text,'tragend'::text,'Alter, sie trägt ihren Regenmantel bei jeder Wanderung, man muss ja trocken bleiben.'::text),
(311569,34619,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, вона ... свій дощовик у кожному поході, треба ж лишатися сухою.'::text,'носить'::text,'носити'::text,'носячи'::text,'Чувак, вона носить свій дощовик у кожному поході, треба ж лишатися сухою.'::text),
(311568,34619,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella ... su chubasquero en cada excursión, hay que mantenerse seca.'::text,'lleva'::text,'llevar'::text,'llevando'::text,'Tío, ella lleva su chubasquero en cada excursión, hay que mantenerse seca.'::text),
(311567,34619,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, elle ... son imperméable à chaque rando, faut rester au sec.'::text,'porte'::text,'porter'::text,'portant'::text,'Mec, elle porte son imperméable à chaque rando, faut rester au sec.'::text),
(311570,34619,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, her yürüyüşte yağmurluğunu ..., kuru kalmak lazım.'::text,'giyer'::text,'giymek'::text,'giyerek'::text,'Kanka, her yürüyüşte yağmurluğunu giyer, kuru kalmak lazım.'::text),
(311571,34619,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, minden túrán ... az esőkabátját, szárazon kell maradni.'::text,'hordja'::text,'hordani'::text,'hordó'::text,'Tesó, minden túrán hordja az esőkabátját, szárazon kell maradni.'::text),
(311574,34620,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Produktziel: Der Regenmantel hält 100 % des ... ab.'::text,'Wassers'::text,'Wassers'::text,'eines Wassers'::text,'Produktziel: Der Regenmantel hält 100 % des Wassers ab.'::text),
(311578,34620,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ціль продукту: дощовик не пропускає 100 % ...'::text,'води'::text,'вод'::text,'води'::text,'Ціль продукту: дощовик не пропускає 100 % води.'::text),
(311577,34620,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo del producto: el chubasquero mantiene fuera el 100 % del ...'::text,'agua'::text,'agua'::text,'un agua'::text,'Objetivo del producto: el chubasquero mantiene fuera el 100 % del agua.'::text),
(311576,34620,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif produit : l''imperméable bloque 100 % de ...'::text,'l''eau'::text,'l''eau'::text,'une eau'::text,'Objectif produit : l''imperméable bloque 100 % de l''eau.'::text),
(311579,34620,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ürün hedefi: yağmurluk ... yüzde 100''ünü dışarıda tutuyor.'::text,'suyun'::text,'suların'::text,'bir suyun'::text,'Ürün hedefi: yağmurluk suyun yüzde 100''ünü dışarıda tutuyor.'::text),
(311580,34620,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Termékcél: az esőkabát a ... 100%-át kint tartja.'::text,'víz'::text,'víz'::text,'egy víz'::text,'Termékcél: az esőkabát a víz 100%-át kint tartja.'::text),
(311583,34621,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier ist so ... Wasser, also trägt sie einen Regenmantel.'::text,'viel'::text,'viele'::text,'eine Menge'::text,'Hier ist so viel Wasser, also trägt sie einen Regenmantel.'::text),
(311587,34621,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тут так ... води, тож вона вдягає дощовик.'::text,'багато'::text,'багато'::text,'багато'::text,'Тут так багато води, тож вона вдягає дощовик.'::text),
(311586,34621,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aquí hay ... agua, así que lleva un chubasquero.'::text,'mucha'::text,'muchas'::text,'un montón de'::text,'Aquí hay mucha agua, así que lleva un chubasquero.'::text),
(311585,34621,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a ... eau ici, alors elle porte un imperméable.'::text,'beaucoup d'''::text,'beaucoup d'''::text,'plein d'''::text,'Il y a beaucoup d'' eau ici, alors elle porte un imperméable.'::text),
(311588,34621,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burada o kadar ... su var ki yağmurluk giyiyor.'::text,'çok'::text,'çok'::text,'çok'::text,'Burada o kadar çok su var ki yağmurluk giyiyor.'::text),
(311589,34621,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan ... víz van itt, hogy esőkabátot visel.'::text,'sok'::text,'sok'::text,'rengeteg'::text,'Olyan sok víz van itt, hogy esőkabátot visel.'::text),
(311592,34622,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'An ihrem roten Regenmantel ... zwei Taschen.'::text,'sind'::text,'ist'::text,'sein'::text,'An ihrem roten Regenmantel sind zwei Taschen.'::text),
(311596,34622,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На її червоному дощовику ... дві кишені.'::text,'є'::text,'є'::text,'бути'::text,'На її червоному дощовику є дві кишені.'::text),
(311595,34622,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dos bolsillos en su chubasquero rojo.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay dos bolsillos en su chubasquero rojo.'::text),
(311594,34622,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... deux poches sur son imperméable rouge.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a deux poches sur son imperméable rouge.'::text),
(311597,34622,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırmızı yağmurluğunda iki cep ...'::text,'var'::text,'var'::text,'olmak'::text,'Kırmızı yağmurluğunda iki cep var.'::text),
(311598,34622,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piros esőkabátján két zseb ...'::text,'van'::text,'van'::text,'lenni'::text,'A piros esőkabátján két zseb van.'::text),
(311601,34623,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Auf dem Schild steht, dass Besucher am Wasserfall einen Regenmantel ...!'::text,'tragen müssen'::text,'tragen müssen'::text,'tragen sollten'::text,'Katastrophe! Auf dem Schild steht, dass Besucher am Wasserfall einen Regenmantel tragen müssen!'::text),
(311605,34623,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! На табличці написано, що відвідувачі ... носити дощовик біля водоспаду!'::text,'мають'::text,'мусять'::text,'мали б'::text,'Катастрофа! На табличці написано, що відвідувачі мають носити дощовик біля водоспаду!'::text),
(311604,34623,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡El cartel dice que los visitantes ... llevar chubasquero cerca de las cataratas!'::text,'tienen que'::text,'deben'::text,'deberían'::text,'¡Desastre! ¡El cartel dice que los visitantes tienen que llevar chubasquero cerca de las cataratas!'::text),
(311603,34623,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Le panneau dit que les visiteurs ... porter un imperméable près des chutes !'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Catastrophe ! Le panneau dit que les visiteurs doivent porter un imperméable près des chutes !'::text),
(311606,34623,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Tabela diyor ki ziyaretçiler şelalenin yakınında yağmurluk ...!'::text,'giymek zorunda'::text,'giymeli'::text,'giymeli'::text,'Felaket! Tabela diyor ki ziyaretçiler şelalenin yakınında yağmurluk giymek zorunda!'::text),
(311607,34623,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A táblán az áll, hogy a látogatóknak esőkabátot ... viselniük a vízesésnél!'::text,'kell'::text,'kell'::text,'kellene'::text,'Katasztrófa! A táblán az áll, hogy a látogatóknak esőkabátot kell viselniük a vízesésnél!'::text),
(311619,34625,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, angeblich ist sie nass geworden, ... sie einen Regenmantel anhatte!'::text,'obwohl'::text,'weil'::text,'also'::text,'Süße, angeblich ist sie nass geworden, obwohl sie einen Regenmantel anhatte!'::text),
(311623,34625,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона промокла, ... була в дощовику!'::text,'хоча'::text,'бо'::text,'тому'::text,'Подруго, кажуть, вона промокла, хоча була в дощовику!'::text),
(311622,34625,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer se mojó, ¡... llevaba chubasquero!'::text,'aunque'::text,'porque'::text,'así que'::text,'Tía, al parecer se mojó, ¡aunque llevaba chubasquero!'::text),
(311621,34625,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle s''est fait tremper, ... elle ait porté un imperméable !'::text,'bien qu'''::text,'parce qu'''::text,'donc'::text,'Meuf, apparemment elle s''est fait tremper, bien qu'' elle ait porté un imperméable !'::text),
(311624,34625,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre ... yağmurluk giymiş olsa da ıslanmış!'::text,'her ne kadar'::text,'çünkü'::text,'bu yüzden'::text,'Kızım, duyduğuma göre her ne kadar yağmurluk giymiş olsa da ıslanmış!'::text),
(311625,34625,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag elázott, ... esőkabát volt rajta!'::text,'bár'::text,'mert'::text,'ezért'::text,'Csajszi, állítólag elázott, bár esőkabát volt rajta!'::text),
(306111,34013,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der große Becher ... viel Kaffee fassen.'::text,'kann'::text,'kann'::text,'ist'::text,'Der große Becher kann viel Kaffee fassen.'::text),
(306115,34013,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Великий кухоль ... вмістити багато кави.'::text,'може'::text,'може'::text,'є'::text,'Великий кухоль може вмістити багато кави.'::text),
(306114,34013,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La taza grande ... contener mucho café.'::text,'puede'::text,'puede'::text,'está'::text,'La taza grande puede contener mucho café.'::text),
(306113,34013,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le grand mug ... contenir beaucoup de café.'::text,'peut'::text,'peut'::text,'est'::text,'Le grand mug peut contenir beaucoup de café.'::text),
(306116,34013,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük kupa çok kahve ...'::text,'alabilir'::text,'alabilir'::text,NULL::text,'Büyük kupa çok kahve alabilir.'::text),
(306117,34013,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagy bögrébe sok kávé ...'::text,'férhet'::text,'férhet'::text,'van'::text,'A nagy bögrébe sok kávé férhet.'::text),
(306129,34015,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da steht ein weißer Becher, und ... Becher ist komplett voll!'::text,'der'::text,'ein'::text,'ein'::text,'Da steht ein weißer Becher, und der Becher ist komplett voll!'::text),
(306133,34015,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Там стоїть білий кухоль, і ... кухоль повністю повний!'::text,''::text,NULL::text,NULL::text,'Там стоїть білий кухоль, і кухоль повністю повний!'::text),
(306132,34015,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahí hay una taza blanca, ¡y ... taza está llenísima!'::text,'la'::text,'una'::text,'una'::text,'Ahí hay una taza blanca, ¡y la taza está llenísima!'::text),
(306131,34015,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un mug blanc est posé là, et ... mug est complètement plein !'::text,'le'::text,'un'::text,'un'::text,'Un mug blanc est posé là, et le mug est complètement plein !'::text),
(306134,34015,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Orada beyaz bir kupa duruyor ve ... kupa ağzına kadar dolu!'::text,''::text,'bir'::text,'bir'::text,'Orada beyaz bir kupa duruyor ve kupa ağzına kadar dolu!'::text),
(306135,34015,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ott áll egy fehér bögre, és ... bögre teljesen tele van!'::text,'a'::text,'egy'::text,'egy'::text,'Ott áll egy fehér bögre, és a bögre teljesen tele van!'::text),
(306138,34016,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Becher auf der Arbeitsplatte ist weiß.'::text,'Dieser'::text,'Diese'::text,'Jene'::text,'Dieser Becher auf der Arbeitsplatte ist weiß.'::text),
(306142,34016,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... кухоль на стільниці білий.'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей кухоль на стільниці білий.'::text),
(306141,34016,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... taza de la encimera es blanca.'::text,'Esta'::text,'Estas'::text,'Esas'::text,'Esta taza de la encimera es blanca.'::text),
(306140,34016,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mug sur le comptoir est blanc.'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Ce mug sur le comptoir est blanc.'::text),
(306143,34016,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tezgâhtaki ... kupa beyaz.'::text,'bu'::text,'bu'::text,'şu'::text,'Tezgâhtaki bu kupa beyaz.'::text),
(306144,34016,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a bögre a pulton fehér.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a bögre a pulton fehér.'::text),
(306147,34017,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Becher ist weiß und ... Henkel ist groß.'::text,'sein'::text,'es ist'::text,'sein'::text,'Der Becher ist weiß und sein Henkel ist groß.'::text),
(306151,34017,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кухоль білий, і ... ручка велика.'::text,'його'::text,'є'::text,'його'::text,'Кухоль білий, і його ручка велика.'::text),
(306150,34017,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La taza es blanca y ... asa es grande.'::text,'su'::text,'es'::text,'su'::text,'La taza es blanca y su asa es grande.'::text),
(306149,34017,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mug est blanc et ... anse est grande.'::text,'son'::text,'c''est'::text,'son'::text,'Le mug est blanc et son anse est grande.'::text),
(306152,34017,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kupa beyaz ve ... sapı büyük.'::text,'onun'::text,NULL::text,'onun'::text,'Kupa beyaz ve onun sapı büyük.'::text),
(306153,34017,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bögre fehér, és ... nagy.'::text,'a füle'::text,NULL::text,'a füle'::text,'A bögre fehér, és a füle nagy.'::text),
(306156,34018,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... ist in dem Becher? Kaffee, muss ja.'::text,'was'::text,'wer'::text,'wo'::text,'Bro, was ist in dem Becher? Kaffee, muss ja.'::text),
(306160,34018,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... в кухлі? Кава, стопудово.'::text,'що'::text,'хто'::text,'де'::text,'Бро, що в кухлі? Кава, стопудово.'::text),
(306159,34018,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿... hay en la taza? Café, seguro.'::text,'qué'::text,'quién'::text,'dónde'::text,'Tío, ¿qué hay en la taza? Café, seguro.'::text),
(306158,34018,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ... est dans le mug ? Du café, forcément.'::text,'qu''est-ce qui'::text,'qui'::text,'où'::text,'Frère, qu''est-ce qui est dans le mug ? Du café, forcément.'::text),
(306161,34018,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kupada ... var? Kahve, kesin.'::text,'ne'::text,'kim'::text,'nerede'::text,'Kanka, kupada ne var? Kahve, kesin.'::text),
(306162,34018,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... van a bögrében? Kávé, biztos.'::text,'mi'::text,'ki'::text,'hol'::text,'Tesó, mi van a bögrében? Kávé, biztos.'::text),
(306165,34019,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Becher Kaffee ist ... 7 Uhr fertig. Meeting-Zeit.'::text,'um'::text,'am'::text,'im'::text,'Der Becher Kaffee ist um 7 Uhr fertig. Meeting-Zeit.'::text),
(306169,34019,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кухоль кави готовий ... 7:00. Час наради.'::text,'о'::text,'на'::text,'у'::text,'Кухоль кави готовий о 7:00. Час наради.'::text),
