(306174,34020,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Team braucht vor dem Meeting ... Becher Kaffee.'::text,'zehn'::text,'zehnte'::text,'Zehnen'::text,'Das Team braucht vor dem Meeting zehn Becher Kaffee.'::text),
(306178,34020,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Команді перед нарадою потрібно ... кухлів кави.'::text,'десять'::text,'десятий'::text,'десятки'::text,'Команді перед нарадою потрібно десять кухлів кави.'::text),
(306177,34020,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El equipo necesita ... tazas de café antes de la reunión.'::text,'diez'::text,'décimas'::text,'diez'::text,'El equipo necesita diez tazas de café antes de la reunión.'::text),
(306176,34020,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipe a besoin de ... mugs de café avant la réunion.'::text,'dix'::text,'dixième'::text,'dix'::text,'L''équipe a besoin de dix mugs de café avant la réunion.'::text),
(306179,34020,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekibin toplantıdan önce ... kupa kahveye ihtiyacı var.'::text,'on'::text,'onuncu'::text,'onlar'::text,'Ekibin toplantıdan önce on kupa kahveye ihtiyacı var.'::text),
