(322275,35809,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... mit einer Hand Tee aus der Teekanne gießen.'::text,'kann'::text,'kann'::text,'kann'::text,'Sie kann mit einer Hand Tee aus der Teekanne gießen.'::text),
(322279,35809,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... наливати чай із чайника однією рукою.'::text,'може'::text,'може'::text,'може'::text,'Вона може наливати чай із чайника однією рукою.'::text),
(322278,35809,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... servir té de la tetera con una mano.'::text,'puede'::text,'puede'::text,'puede'::text,'Ella puede servir té de la tetera con una mano.'::text),
(322277,35809,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... verser du thé de la théière d''une seule main.'::text,'peut'::text,'peut'::text,'peut'::text,'Elle peut verser du thé de la théière d''une seule main.'::text),
(322280,35809,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demlikten tek eliyle çay ...'::text,'koyabilir'::text,'koyabilir'::text,'koyabilir'::text,'Demlikten tek eliyle çay koyabilir.'::text),
(322281,35809,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy kézzel ... teát a teáskannából.'::text,'tölthet'::text,'tölthet'::text,'tölthet'::text,'Egy kézzel tölthet teát a teáskannából.'::text),
(322284,35810,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie braucht für die ganze Party ..., Bro.'::text,'2 Teekannen'::text,'2 Teekanne'::text,'2 Teekannen'::text,'Yo, sie braucht für die ganze Party 2 Teekannen, Bro.'::text),
(322288,35810,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, їй знадобиться ... на всю вечірку, бро.'::text,'2 чайники'::text,'2 чайник'::text,'2 чайники'::text,'Йо, їй знадобиться 2 чайники на всю вечірку, бро.'::text),
(322287,35810,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eh, va a necesitar ... para toda la fiesta, tío.'::text,'2 teteras'::text,'2 tetera'::text,'2 teteras'::text,'Eh, va a necesitar 2 teteras para toda la fiesta, tío.'::text),
(322286,35810,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, elle va avoir besoin de ... pour toute la soirée, frère.'::text,'2 théières'::text,'2 théière'::text,'2 théières'::text,'Yo, elle va avoir besoin de 2 théières pour toute la soirée, frère.'::text),
(322289,35810,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bütün parti için ... lazım olacak, kardeşim.'::text,'2 demlik'::text,'2 demlik'::text,'2 demlikler'::text,'Kanka, bütün parti için 2 demlik lazım olacak, kardeşim.'::text),
(322290,35810,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, az egész bulira ... kell majd neki, tesó.'::text,'2 teáskanna'::text,'2 teáskanna'::text,'2 teáskanna'::text,'Figyu, az egész bulira 2 teáskanna kell majd neki, tesó.'::text),
(322302,35812,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Teekanne ist für Tee, also gießt sie Tee daraus.'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Diese Teekanne ist für Tee, also gießt sie Tee daraus.'::text),
(322306,35812,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... чайник для чаю, тож вона наливає з нього чай.'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей чайник для чаю, тож вона наливає з нього чай.'::text),
(322305,35812,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tetera es para té, así que sirve té de ella.'::text,'Esta'::text,'Estas'::text,'Esas'::text,'Esta tetera es para té, así que sirve té de ella.'::text),
(322304,35812,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... théière est pour le thé, donc elle en verse du thé.'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette théière est pour le thé, donc elle en verse du thé.'::text),
(322307,35812,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... demlik çay için, bu yüzden ondan çay koyuyor.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu demlik çay için, bu yüzden ondan çay koyuyor.'::text),
(322308,35812,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a teáskanna teának való, ezért teát tölt belőle.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a teáskanna teának való, ezért teát tölt belőle.'::text),
(322311,35813,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du gießt Tee aus ... Teekanne wie ein Profi.'::text,'deiner'::text,'du'::text,'deine'::text,'Ehrlich gesagt, du gießt Tee aus deiner Teekanne wie ein Profi.'::text),
(322315,35813,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти наливаєш чай зі ... чайника як профі.'::text,'свого'::text,'ти'::text,'твій'::text,'Не буду брехати, ти наливаєш чай зі свого чайника як профі.'::text),
(322314,35813,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, sirves el té de ... tetera como una pro.'::text,'tu'::text,'tú'::text,'la tuya'::text,'No voy a mentir, sirves el té de tu tetera como una pro.'::text),
(322313,35813,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu verses le thé de ... théière comme une pro.'::text,'ta'::text,'toi'::text,'la tienne'::text,'Je vais pas mentir, tu verses le thé de ta théière comme une pro.'::text),
(322316,35813,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, ... demliğinden profesyonel gibi çay koyuyorsun.'::text,'senin'::text,'sen'::text,'seninki'::text,'Yalan yok, senin demliğinden profesyonel gibi çay koyuyorsun.'::text),
(322317,35813,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, úgy töltesz teát ..., mint egy profi.'::text,'a teáskannádból'::text,'te'::text,'a tiéd'::text,'Nem hazudok, úgy töltesz teát a teáskannádból, mint egy profi.'::text),
(322320,35814,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... gießt du Tee so perfekt aus dieser Teekanne? Respekt.'::text,'Wie'::text,'Wer'::text,'Wann'::text,'Wie gießt du Tee so perfekt aus dieser Teekanne? Respekt.'::text),
(322324,35814,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ти так ідеально наливаєш чай із того чайника? Респект.'::text,'Як'::text,'Хто'::text,'Коли'::text,'Як ти так ідеально наливаєш чай із того чайника? Респект.'::text),
(322323,35814,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... sirves el té tan perfectamente de esa tetera? Respeto.'::text,'Cómo'::text,'Quién'::text,'Cuándo'::text,'¿Cómo sirves el té tan perfectamente de esa tetera? Respeto.'::text),
(322322,35814,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fais-tu pour verser le thé si parfaitement de cette théière ? Respect.'::text,'Comment'::text,'Qui'::text,'Quand'::text,'Comment fais-tu pour verser le thé si parfaitement de cette théière ? Respect.'::text),
(322325,35814,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O demlikten ... bu kadar kusursuz çay koyuyorsun? Helal.'::text,'nasıl'::text,'kim'::text,'ne zaman'::text,'O demlikten nasıl bu kadar kusursuz çay koyuyorsun? Helal.'::text),
(322326,35814,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... töltesz ilyen tökéletesen teát abból a teáskannából? Respekt.'::text,'Hogyan'::text,'Ki'::text,'Mikor'::text,'Hogyan töltesz ilyen tökéletesen teát abból a teáskannából? Respekt.'::text),
(322329,35815,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du stellst die Teekanne wie ein Profi ... den Tisch.'::text,'auf'::text,'in'::text,'an'::text,'Ehrlich, du stellst die Teekanne wie ein Profi auf den Tisch.'::text),
(322333,35815,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ставиш чайник ... стіл як профі.'::text,'на'::text,'у'::text,'біля'::text,'Чесно, ти ставиш чайник на стіл як профі.'::text),
(322332,35815,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, pones la tetera ... la mesa como una pro.'::text,'en'::text,'en'::text,'a'::text,'La verdad, pones la tetera en la mesa como una pro.'::text),
(322331,35815,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu poses la théière ... la table comme une pro.'::text,'sur'::text,'dans'::text,'à'::text,'Franchement, tu poses la théière sur la table comme une pro.'::text),
(322334,35815,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası demliği masanın ... profesyonel gibi koyuyorsun.'::text,'üstüne'::text,'içine'::text,NULL::text,'Açıkçası demliği masanın üstüne profesyonel gibi koyuyorsun.'::text),
(322335,35815,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, úgy teszed le a teáskannát ..., mint egy profi.'::text,'az asztalra'::text,'az asztalba'::text,'az asztalnál'::text,'Őszintén, úgy teszed le a teáskannát az asztalra, mint egy profi.'::text),
(322338,35816,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie gießt Tee aus einer Teekanne und Saft in ... Gläser.'::text,'drei'::text,'dritte'::text,'Dreien'::text,'Sie gießt Tee aus einer Teekanne und Saft in drei Gläser.'::text),
(322342,35816,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона наливає чай з одного чайника, а сік — у ... склянки.'::text,'три'::text,'третю'::text,'трійки'::text,'Вона наливає чай з одного чайника, а сік — у три склянки.'::text),
(322341,35816,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sirve té de una tetera y zumo en ... vasos.'::text,'tres'::text,'terceros'::text,'tres'::text,'Sirve té de una tetera y zumo en tres vasos.'::text),
(322340,35816,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle verse du thé d''une théière et du jus dans ... verres.'::text,'trois'::text,'troisièmes'::text,'trois'::text,'Elle verse du thé d''une théière et du jus dans trois verres.'::text),
(322343,35816,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir demlikten çay, ... bardağa da meyve suyu koyuyor.'::text,'üç'::text,'üçüncü'::text,'üçler'::text,'Bir demlikten çay, üç bardağa da meyve suyu koyuyor.'::text),
(322344,35816,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy teáskannából teát tölt, és ... pohárba gyümölcslevet.'::text,'három'::text,'harmadik'::text,'hármasok'::text,'Egy teáskannából teát tölt, és három pohárba gyümölcslevet.'::text),
(326757,36307,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Wetter ... gestern schlecht, weil es nicht gut war.'::text,'war'::text,'ist'::text,NULL::text,'Das Wetter war gestern schlecht, weil es nicht gut war.'::text),
(326761,36307,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Погода ... вчора погана, бо вона не була гарною.'::text,'була'::text,'є'::text,NULL::text,'Погода була вчора погана, бо вона не була гарною.'::text),
(326760,36307,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tiempo ... malo ayer porque no era bueno.'::text,'fue'::text,'es'::text,NULL::text,'El tiempo fue malo ayer porque no era bueno.'::text),
(326759,36307,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps ... mauvais hier parce qu''il n''était pas bon.'::text,'était'::text,'est'::text,NULL::text,'Le temps était mauvais hier parce qu''il n''était pas bon.'::text),
(326762,36307,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hava dün kötü ... çünkü iyi değildi.'::text,'idi'::text,NULL::text,NULL::text,'Hava dün kötü idi çünkü iyi değildi.'::text),
(326763,36307,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idő tegnap rossz ..., mert nem volt jó.'::text,'volt'::text,NULL::text,NULL::text,'Az idő tegnap rossz volt, mert nem volt jó.'::text),
(326766,36308,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwie ikonisch: Gerade ... du das schlechte Wetter mit Stil.'::text,'genießt'::text,'genießt'::text,'genießt'::text,'Irgendwie ikonisch: Gerade genießt du das schlechte Wetter mit Stil.'::text),
(326770,36308,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якось культово: саме зараз ти стильно ... поганою погодою.'::text,'насолоджуєшся'::text,'насолоджуєшся'::text,'насолоджуєшся'::text,'Якось культово: саме зараз ти стильно насолоджуєшся поганою погодою.'::text),
(326769,36308,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bastante icónico: ahora mismo ... del mal tiempo con estilo.'::text,'estás disfrutando'::text,'disfrutas'::text,'estás disfrutando'::text,'Bastante icónico: ahora mismo estás disfrutando del mal tiempo con estilo.'::text),
(326768,36308,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plutôt iconique : là, tu ... du mauvais temps avec style.'::text,'es en train de profiter'::text,'profites'::text,'es en train de profiter'::text,'Plutôt iconique : là, tu es en train de profiter du mauvais temps avec style.'::text),
(326771,36308,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Baya ikonik: şu an tarzınla kötü havanın ...'::text,'tadını çıkarıyorsun'::text,'tadını çıkarırsın'::text,'tadını çıkarıyorsun'::text,'Baya ikonik: şu an tarzınla kötü havanın tadını çıkarıyorsun.'::text),
(326772,36308,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elég ikonikus: most épp stílusosan ... a rossz időt.'::text,'élvezed'::text,'élvezed'::text,'élvezed'::text,'Elég ikonikus: most épp stílusosan élvezed a rossz időt.'::text),
(326775,36309,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei schlechtem Wetter bleibt er normalerweise drinnen, aber heute ... er draußen.'::text,'steht'::text,'steht'::text,NULL::text,'Bei schlechtem Wetter bleibt er normalerweise drinnen, aber heute steht er draußen.'::text),
(326779,36309,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У погану погоду він зазвичай сидить удома, але сьогодні ... надворі.'::text,'стоїть'::text,'стоїть'::text,NULL::text,'У погану погоду він зазвичай сидить удома, але сьогодні стоїть надворі.'::text),
(326778,36309,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con mal tiempo normalmente se queda dentro, pero hoy ... fuera.'::text,'está de pie'::text,'está de pie'::text,NULL::text,'Con mal tiempo normalmente se queda dentro, pero hoy está de pie fuera.'::text),
(326777,36309,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Par mauvais temps, il reste d''habitude à l''intérieur, mais aujourd''hui il ... dehors.'::text,'est debout'::text,'se tient'::text,NULL::text,'Par mauvais temps, il reste d''habitude à l''intérieur, mais aujourd''hui il est debout dehors.'::text),
(326780,36309,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kötü havada genelde içeride kalır ama bugün dışarıda ...'::text,'duruyor'::text,'durur'::text,NULL::text,'Kötü havada genelde içeride kalır ama bugün dışarıda duruyor.'::text),
(326781,36309,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rossz időben általában bent marad, de ma kint ...'::text,'áll'::text,'áll'::text,NULL::text,'Rossz időben általában bent marad, de ma kint áll.'::text),
(326784,36310,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Wetter ist grau, also glaube ich, dass es bald wieder ...'::text,'regnen wird'::text,'regnet'::text,'regnete'::text,'Das Wetter ist grau, also glaube ich, dass es bald wieder regnen wird.'::text),
(326788,36310,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Погода сіра, тож, думаю, скоро знову ...'::text,'піде дощ'::text,'іде дощ'::text,'йшов дощ'::text,'Погода сіра, тож, думаю, скоро знову піде дощ.'::text),
(326787,36310,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tiempo está gris, así que creo que pronto ... otra vez.'::text,'lloverá'::text,'llueve'::text,'llovió'::text,'El tiempo está gris, así que creo que pronto lloverá otra vez.'::text),
(326786,36310,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps est gris, donc je pense qu''il ... bientôt à nouveau.'::text,'pleuvra'::text,'pleut'::text,'a plu'::text,'Le temps est gris, donc je pense qu''il pleuvra bientôt à nouveau.'::text),
(326789,36310,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hava gri, bu yüzden bence yakında yine yağmur ...'::text,'yağacak'::text,'yağar'::text,'yağdı'::text,'Hava gri, bu yüzden bence yakında yine yağmur yağacak.'::text),
(326790,36310,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szürke az idő, szóval szerintem hamarosan megint ...'::text,'esni fog'::text,'esik'::text,'esett'::text,'Szürke az idő, szóval szerintem hamarosan megint esni fog.'::text),
(326793,36311,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... er sich für dieses Wetter einen größeren Regenschirm kaufen.'::text,'wird'::text,'wird'::text,'werden'::text,'Bestie, angeblich wird er sich für dieses Wetter einen größeren Regenschirm kaufen.'::text),
(326797,36311,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... купити більшу парасолю для такої погоди.'::text,'збирається'::text,'збирається'::text,'збираються'::text,'Подруго, кажуть, він збирається купити більшу парасолю для такої погоди.'::text),
(326796,36311,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... comprarse un paraguas más grande para este tiempo.'::text,'va a'::text,'va a'::text,'van a'::text,'Tía, al parecer va a comprarse un paraguas más grande para este tiempo.'::text),
(326795,36311,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment il ... acheter un plus grand parapluie pour ce temps.'::text,'va'::text,'va'::text,'vont'::text,'Bestie, apparemment il va acheter un plus grand parapluie pour ce temps.'::text),
(326798,36311,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre bu hava için daha büyük bir şemsiye ...'::text,'alacak'::text,'alacak'::text,'alacaklar'::text,'Kanka, duyduğuma göre bu hava için daha büyük bir şemsiye alacak.'::text),
(326799,36311,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag egy nagyobb esernyőt ... venni erre az időre.'::text,'fog'::text,'fog'::text,'fognak'::text,'Csajszi, állítólag egy nagyobb esernyőt fog venni erre az időre.'::text),
(326802,36312,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, diese dunklen Wolken? Es ... in einer Minute regnen, das Wetter ist durch.'::text,'wird'::text,'wird'::text,NULL::text,'Bro, diese dunklen Wolken? Es wird in einer Minute regnen, das Wetter ist durch.'::text),
(326806,36312,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ті темні хмари? За хвилину ..., погоді кінець.'::text,'піде дощ'::text,'піде дощ'::text,NULL::text,'Бро, ті темні хмари? За хвилину піде дощ, погоді кінець.'::text),
(326805,36312,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿esas nubes negras? En un minuto ..., el tiempo está fatal.'::text,'va a llover'::text,'lloverá'::text,NULL::text,'Tío, ¿esas nubes negras? En un minuto va a llover, el tiempo está fatal.'::text),
(326804,36312,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ces nuages noirs ? Il ... dans une minute, la météo est foutue.'::text,'va pleuvoir'::text,'pleuvra'::text,NULL::text,'Frère, ces nuages noirs ? Il va pleuvoir dans une minute, la météo est foutue.'::text),
(326807,36312,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, şu kara bulutlar? Bir dakikaya yağmur ..., hava bitti.'::text,'yağacak'::text,'yağacak'::text,NULL::text,'Kanka, şu kara bulutlar? Bir dakikaya yağmur yağacak, hava bitti.'::text),
(326808,36312,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azok a sötét felhők? Egy percen belül ... esni, az időnek annyi.'::text,'fog'::text,'fog'::text,NULL::text,'Tesó, azok a sötét felhők? Egy percen belül fog esni, az időnek annyi.'::text),
(326811,36313,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, dieses Wetter hat heute viel zu viel ...'::text,'Regen'::text,'Regen'::text,'einen Regen'::text,'Nee, dieses Wetter hat heute viel zu viel Regen.'::text),
(326815,36313,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, у цієї погоди сьогодні забагато ...'::text,'дощу'::text,'дощів'::text,'дощу'::text,'Не, у цієї погоди сьогодні забагато дощу.'::text),
(326814,36313,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, este tiempo trae hoy demasiada ...'::text,'lluvia'::text,'lluvia'::text,'una lluvia'::text,'Qué va, este tiempo trae hoy demasiada lluvia.'::text),
(326813,36313,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, ce temps a beaucoup trop de ... aujourd''hui.'::text,'pluie'::text,'pluie'::text,'une pluie'::text,'Non, ce temps a beaucoup trop de pluie aujourd''hui.'::text),
(326816,36313,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok artık, bu havada bugün çok fazla ... var.'::text,'yağmur'::text,'yağmurlar'::text,'bir yağmur'::text,'Yok artık, bu havada bugün çok fazla yağmur var.'::text),
(326817,36313,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, ebben az időben ma túl sok ... van.'::text,'eső'::text,'eső'::text,'egy eső'::text,'Á, ebben az időben ma túl sok eső van.'::text),
(327675,36409,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es ... so windig, und du liebst es trotzdem. Respekt.'::text,'ist'::text,'sind'::text,'bin'::text,'Es ist so windig, und du liebst es trotzdem. Respekt.'::text),
(327679,36409,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Так вітряно ..., а ти все одно це любиш. Респект.'::text,''::text,NULL::text,NULL::text,'Так вітряно, а ти все одно це любиш. Респект.'::text),
(327678,36409,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tanto viento, y aun así te encanta. Respeto.'::text,'Hace'::text,'Hacen'::text,'Hago'::text,'Hace tanto viento, y aun así te encanta. Respeto.'::text),
(327677,36409,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... tellement de vent, et tu adores quand même. Respect.'::text,'fait'::text,'font'::text,'fais'::text,'Il fait tellement de vent, et tu adores quand même. Respect.'::text),
(327680,36409,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hava o kadar rüzgârlı ... ve sen yine de bayılıyorsun. Helal.'::text,''::text,NULL::text,NULL::text,'Hava o kadar rüzgârlı ve sen yine de bayılıyorsun. Helal.'::text),
(327681,36409,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan szeles az idő ..., és te mégis imádod. Respekt.'::text,''::text,NULL::text,'vagyok'::text,'Olyan szeles az idő, és te mégis imádod. Respekt.'::text),
(327684,36410,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie du an windigen Tagen die Arme weit ...? Ikonisch.'::text,'ausbreitest'::text,'ausbreitet'::text,'ausbreitend'::text,'Wie du an windigen Tagen die Arme weit ausbreitest? Ikonisch.'::text),
(327688,36410,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Те, як ти у вітряні дні широко ... руки? Культово.'::text,'розводиш'::text,'розводить'::text,'розводячи'::text,'Те, як ти у вітряні дні широко розводиш руки? Культово.'::text),
(327687,36410,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿La forma en que ... los brazos en los días de viento? Icónico.'::text,'abres'::text,'abre'::text,'abriendo'::text,'¿La forma en que abres los brazos en los días de viento? Icónico.'::text),
(327686,36410,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La façon dont tu ... grand les bras les jours de vent ? Iconique.'::text,'ouvres'::text,'ouvre'::text,'ouvrant'::text,'La façon dont tu ouvres grand les bras les jours de vent ? Iconique.'::text),
(327689,36410,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rüzgârlı günlerde kollarını iki yana ..., değil mi? İkonik.'::text,'açarsın'::text,'açar'::text,'açarak'::text,'Rüzgârlı günlerde kollarını iki yana açarsın, değil mi? İkonik.'::text),
(327690,36410,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahogy szeles napokon szélesre ... a karodat? Ikonikus.'::text,'tárod'::text,'tárja'::text,'táró'::text,'Ahogy szeles napokon szélesre tárod a karodat? Ikonikus.'::text),
(327702,36412,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'An windigen Tagen ist die Strandpromenade ... als die Straße.'::text,'windiger'::text,'windiger'::text,'am windigsten'::text,'An windigen Tagen ist die Strandpromenade windiger als die Straße.'::text),
(327706,36412,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У вітряні дні набережна ... за вулицю.'::text,'вітряніша'::text,'вітряніша'::text,'найвітряніша'::text,'У вітряні дні набережна вітряніша за вулицю.'::text),
(327705,36412,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En los días de viento, el paseo marítimo está ... que la calle.'::text,'más ventoso'::text,'más ventoso'::text,'el más ventoso'::text,'En los días de viento, el paseo marítimo está más ventoso que la calle.'::text),
(327704,36412,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les jours de vent, le front de mer est ... que la rue.'::text,'plus venteux'::text,'plus venteux'::text,'le plus venteux'::text,'Les jours de vent, le front de mer est plus venteux que la rue.'::text),
(327707,36412,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rüzgârlı günlerde sahil caddesi sokaktan ...'::text,'daha rüzgârlı'::text,'daha rüzgârlı'::text,'en rüzgârlı'::text,'Rüzgârlı günlerde sahil caddesi sokaktan daha rüzgârlı.'::text),
(327708,36412,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szeles napokon a tengerpart ..., mint az utca.'::text,'szelesebb'::text,'szelesebb'::text,'legszelesebb'::text,'Szeles napokon a tengerpart szelesebb, mint az utca.'::text),
(327711,36413,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, es ist so windig, dass sie ihre Kapuze ..., ohne Witz.'::text,'festhalten muss'::text,'festhalten muss'::text,'festhalten sollte'::text,'Bro, es ist so windig, dass sie ihre Kapuze festhalten muss, ohne Witz.'::text),
(327715,36413,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, так вітряно, що вона ... тримати капюшон, без жартів.'::text,'має'::text,'мусить'::text,'мала б'::text,'Бро, так вітряно, що вона має тримати капюшон, без жартів.'::text),
(327714,36413,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, hace tanto viento que ... sujetarse la capucha, en serio.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Tío, hace tanto viento que tiene que sujetarse la capucha, en serio.'::text),
(327713,36413,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il y a tellement de vent qu''elle ... tenir sa capuche, sans mentir.'::text,'doit'::text,'doit'::text,'devrait'::text,'Frère, il y a tellement de vent qu''elle doit tenir sa capuche, sans mentir.'::text),
(327716,36413,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o kadar rüzgâr var ki kapüşonunu ..., cidden.'::text,'tutmak zorunda'::text,'tutmalı'::text,'tutmalı'::text,'Kanka, o kadar rüzgâr var ki kapüşonunu tutmak zorunda, cidden.'::text),
(327717,36413,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, annyira fúj a szél, hogy fognia ... a kapucniját, komolyan.'::text,'kell'::text,'kell'::text,'kellene'::text,'Tesó, annyira fúj a szél, hogy fognia kell a kapucniját, komolyan.'::text),
(327720,36414,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, viel zu windig, Alter. Du ... von dem Geländer wegbleiben.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Nee, viel zu windig, Alter. Du solltest von dem Geländer wegbleiben.'::text),
(327724,36414,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, надто вітряно, чувак. Ти ... триматися подалі від того поруччя.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Не, надто вітряно, чувак. Ти мав би триматися подалі від того поруччя.'::text),
(327723,36414,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, hace demasiado viento, tío. ... alejarte de esa barandilla.'::text,'Deberías'::text,'Deberías'::text,'Deberías'::text,'Qué va, hace demasiado viento, tío. Deberías alejarte de esa barandilla.'::text),
(327722,36414,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, beaucoup trop de vent, mec. Tu ... rester loin de cette rambarde.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Non, beaucoup trop de vent, mec. Tu devrais rester loin de cette rambarde.'::text),
(327725,36414,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, rüzgâr çok fazla, kanka. O korkuluktan uzak ...'::text,'durmalısın'::text,'durmalısın'::text,'durmalısın'::text,'Yok, rüzgâr çok fazla, kanka. O korkuluktan uzak durmalısın.'::text),
(327726,36414,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, túl szeles van, tesó. Távol ... maradnod attól a korláttól.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Á, túl szeles van, tesó. Távol kellene maradnod attól a korláttól.'::text),
(327729,36415,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bericht zum windigen Tag: Die Wellen schlagen 5-mal pro Minute ... gegen das Geländer.'::text,'hart'::text,'kaum'::text,'robust'::text,'Bericht zum windigen Tag: Die Wellen schlagen 5-mal pro Minute hart gegen das Geländer.'::text),
(327733,36415,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт про вітряний день: хвилі ... б''ють у поруччя 5 разів на хвилину.'::text,'сильно'::text,'ледве'::text,'витривалий'::text,'Звіт про вітряний день: хвилі сильно б''ють у поруччя 5 разів на хвилину.'::text),
(327732,36415,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe del día de viento: las olas golpean la barandilla ... 5 veces por minuto.'::text,'con fuerza'::text,'apenas'::text,'resistente'::text,'Informe del día de viento: las olas golpean la barandilla con fuerza 5 veces por minuto.'::text),
(327731,36415,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport jour de vent : les vagues frappent la rambarde ... 5 fois par minute.'::text,'fort'::text,'à peine'::text,'robuste'::text,'Rapport jour de vent : les vagues frappent la rambarde fort 5 fois par minute.'::text),
(327734,36415,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rüzgârlı gün raporu: dalgalar dakikada 5 kez korkuluğa ... çarpıyor.'::text,'sertçe'::text,'zar zor'::text,'dayanıklı'::text,'Rüzgârlı gün raporu: dalgalar dakikada 5 kez korkuluğa sertçe çarpıyor.'::text),
(327735,36415,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szeles napi jelentés: a hullámok percenként 5-ször ... csapódnak a korlátnak.'::text,'erősen'::text,'alig'::text,'strapabíró'::text,'Szeles napi jelentés: a hullámok percenként 5-ször erősen csapódnak a korlátnak.'::text),
(317874,35320,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! Das ganze Feld ... verschneit und kalt! Das ist das Schlimmste!'::text,'ist'::text,'sind'::text,'bin'::text,'Nein! Das ganze Feld ist verschneit und kalt! Das ist das Schlimmste!'::text),
(317878,35320,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! Усе поле ... засніжене й холодне! Це найгірше!'::text,'є'::text,'є'::text,'є'::text,'Ні! Усе поле є засніжене й холодне! Це найгірше!'::text),
(317877,35320,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡Todo el campo ... nevado y frío! ¡Esto es lo peor!'::text,'está'::text,'están'::text,'estoy'::text,'¡No! ¡Todo el campo está nevado y frío! ¡Esto es lo peor!'::text),
(317876,35320,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! Tout le champ ... enneigé et froid ! C''est le pire !'::text,'est'::text,'sont'::text,'suis'::text,'Non ! Tout le champ est enneigé et froid ! C''est le pire !'::text),
(317879,35320,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! Bütün alan karlı ve soğuk ...! Bu en kötüsü!'::text,''::text,NULL::text,NULL::text,'Hayır! Bütün alan karlı ve soğuk! Bu en kötüsü!'::text),
(317880,35320,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! Az egész mező havas és hideg ...! Ez a legrosszabb!'::text,''::text,NULL::text,'vagyok'::text,'Ne! Az egész mező havas és hideg! Ez a legrosszabb!'::text),
(317892,35322,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... heute Morgen die Flagge auf dem verschneiten Feld.'::text,'hissten'::text,'hissten'::text,'hisst'::text,'Sie hissten heute Morgen die Flagge auf dem verschneiten Feld.'::text),
(317896,35322,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... прапор на засніженому полі сьогодні вранці.'::text,'підняли'::text,'підняли'::text,'піднімає'::text,'Вони підняли прапор на засніженому полі сьогодні вранці.'::text),
(317895,35322,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta mañana ... la bandera en el campo nevado.'::text,'han izado'::text,'han izado'::text,'iza'::text,'Esta mañana han izado la bandera en el campo nevado.'::text),
(317894,35322,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... le drapeau sur le champ enneigé ce matin.'::text,'ont hissé'::text,'ont hissé'::text,'hisse'::text,'Ils ont hissé le drapeau sur le champ enneigé ce matin.'::text),
(317897,35322,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabah karlı alanda bayrağı ...'::text,'göndere çektiler'::text,'göndere çektiler'::text,'göndere çeker'::text,'Bu sabah karlı alanda bayrağı göndere çektiler.'::text),
(317898,35322,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma reggel ... a zászlót a havas mezőn.'::text,'felhúzták'::text,'felhúzták'::text,'felhúzza'::text,'Ma reggel felhúzták a zászlót a havas mezőn.'::text),
(317901,35323,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, gestern ... sie die Flagge im verschneiten Wind, irgendwie ikonisch.'::text,'hissten'::text,'hissen'::text,NULL::text,'Yo, gestern hissten sie die Flagge im verschneiten Wind, irgendwie ikonisch.'::text),
(317905,35323,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, учора вони ... прапор на сніжному вітрі, якось культово.'::text,'підняли'::text,'піднімають'::text,NULL::text,'Йо, учора вони підняли прапор на сніжному вітрі, якось культово.'::text),
(317904,35323,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ayer ... la bandera con el viento nevado, bastante icónico.'::text,'izaron'::text,'izan'::text,NULL::text,'Tío, ayer izaron la bandera con el viento nevado, bastante icónico.'::text),
(317903,35323,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, hier ils ... le drapeau dans le vent de neige, assez iconique.'::text,'ont hissé'::text,'hissent'::text,NULL::text,'Yo, hier ils ont hissé le drapeau dans le vent de neige, assez iconique.'::text),
(317906,35323,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dün karlı rüzgârda bayrağı ..., bayağı ikonik.'::text,'göndere çektiler'::text,'göndere çekerler'::text,NULL::text,'Kanka, dün karlı rüzgârda bayrağı göndere çektiler, bayağı ikonik.'::text),
(317907,35323,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, tegnap ... a zászlót a havas szélben, elég ikonikus.'::text,'felhúzták'::text,'felhúzzák'::text,NULL::text,'Figyu, tegnap felhúzták a zászlót a havas szélben, elég ikonikus.'::text),
(317919,35325,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es ist verschneit, weil da Schnee ist, und jetzt ... sie die Flagge.'::text,'hissen'::text,'hissen'::text,NULL::text,'Es ist verschneit, weil da Schnee ist, und jetzt hissen sie die Flagge.'::text),
(317923,35325,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тут сніжно, бо є сніг, і зараз вони ... прапор.'::text,'піднімають'::text,'піднімають'::text,NULL::text,'Тут сніжно, бо є сніг, і зараз вони піднімають прапор.'::text),
(317922,35325,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está nevado porque hay nieve, y ahora ... la bandera.'::text,'están izando'::text,'izan'::text,NULL::text,'Está nevado porque hay nieve, y ahora están izando la bandera.'::text),
(317921,35325,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est enneigé parce qu''il y a de la neige, et maintenant ils ... le drapeau.'::text,'sont en train de hisser'::text,'hissent'::text,NULL::text,'C''est enneigé parce qu''il y a de la neige, et maintenant ils sont en train de hisser le drapeau.'::text),
(317924,35325,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karlı çünkü kar var, ve şimdi bayrağı ...'::text,'göndere çekiyorlar'::text,'göndere çekerler'::text,NULL::text,'Karlı çünkü kar var, ve şimdi bayrağı göndere çekiyorlar.'::text),
(317925,35325,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havas, mert hó van, és most ... a zászlót.'::text,'húzzák fel'::text,'húzzák fel'::text,NULL::text,'Havas, mert hó van, és most húzzák fel a zászlót.'::text),
(317928,35326,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist der ... Ort der Welt! Nie wieder!'::text,'verschneiteste'::text,'verschneiteste'::text,'verschneitere'::text,'Das ist der verschneiteste Ort der Welt! Nie wieder!'::text),
(317932,35326,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це ... місце у світі! Більше ніколи!'::text,'найсніжніше'::text,'найсніжніше'::text,'сніжніше'::text,'Це найсніжніше місце у світі! Більше ніколи!'::text),
(317931,35326,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este es el lugar ... del mundo! ¡Nunca más!'::text,'más nevado'::text,'más nevado'::text,'más nevado'::text,'¡Este es el lugar más nevado del mundo! ¡Nunca más!'::text),
(317930,35326,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est l''endroit ... du monde ! Plus jamais !'::text,'le plus enneigé'::text,'le plus enneigé'::text,'plus enneigé'::text,'C''est l''endroit le plus enneigé du monde ! Plus jamais !'::text),
(317933,35326,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burası dünyanın ... yeri! Bir daha asla!'::text,'en karlı'::text,'en karlı'::text,'daha karlı'::text,'Burası dünyanın en karlı yeri! Bir daha asla!'::text),
(317934,35326,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a világ ... helye! Soha többé!'::text,'leghavasabb'::text,'leghavasabb'::text,'havasabb'::text,'Ez a világ leghavasabb helye! Soha többé!'::text),
(317937,35327,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Flagge flattert ... im verschneiten Wind! Absolut verrückt!'::text,'wild'::text,'wild'::text,'wild'::text,'Die Flagge flattert wild im verschneiten Wind! Absolut verrückt!'::text),
(317941,35327,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прапор ... майорить на сніжному вітрі! Просто божевілля!'::text,'шалено'::text,'шалений'::text,'шалено'::text,'Прапор шалено майорить на сніжному вітрі! Просто божевілля!'::text),
(317940,35327,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La bandera ondea ... con el viento nevado! ¡Una locura total!'::text,'salvajemente'::text,'salvaje'::text,'salvajemente'::text,'¡La bandera ondea salvajemente con el viento nevado! ¡Una locura total!'::text),
(317939,35327,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le drapeau claque ... dans le vent de neige ! Complètement fou !'::text,'sauvagement'::text,'sauvage'::text,'sauvagement'::text,'Le drapeau claque sauvagement dans le vent de neige ! Complètement fou !'::text),
(317942,35327,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bayrak karlı rüzgârda ... dalgalanıyor! Resmen çılgınca!'::text,'çılgınca'::text,'çılgın'::text,'çılgınca'::text,'Bayrak karlı rüzgârda çılgınca dalgalanıyor! Resmen çılgınca!'::text),
(317943,35327,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zászló ... lobog a havas szélben! Abszolút őrület!'::text,'vadul'::text,'vad'::text,'vadul'::text,'A zászló vadul lobog a havas szélben! Abszolút őrület!'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
